{
  "extends": ["next/core-web-vitals"],
  "rules": {
    "no-console": ["warn", { "allow": ["warn", "error"] }]
  }
}

import { NextResponse, type NextRequest } from "next/server";
import { updateSession } from "@/lib/supabase/middleware";

/**
 * Protects the `(auth)` route group (Dashboard, Company Profile, History,
 * Billing) at the edge, before any Server Component renders — avoids a
 * flash of protected content and keeps the redirect-to-login decision in
 * one place rather than duplicated per page.
 *
 * The (auth) group's own layout (app/(auth)/layout.tsx) re-checks the user
 * server-side as defense in depth — middleware can be bypassed by direct
 * fetches to a Server Action/Route Handler in edge cases, the layout check
 * cannot.
 */
const PROTECTED_PATHS = ["/dashboard", "/profile", "/history", "/settings"];

export async function middleware(request: NextRequest) {
  const { response, user } = await updateSession(request);

  const isProtected = PROTECTED_PATHS.some((path) =>
    request.nextUrl.pathname.startsWith(path),
  );

  if (isProtected && !user) {
    const loginUrl = new URL("/login", request.url);
    loginUrl.searchParams.set("next", request.nextUrl.pathname);
    return NextResponse.redirect(loginUrl);
  }

  return response;
}

export const config = {
  matcher: [
    /*
     * Run on everything except static assets, images and the PWA files —
     * those never need a session refresh and skipping them keeps
     * navigation fast.
     */
    "/((?!_next/static|_next/image|favicon.ico|manifest.json|sw.js|icons/).*)",
  ],
};

/** @type {import('next').NextConfig} */
const nextConfig = {
  reactStrictMode: true,
  // PWA service worker is registered manually (see app/layout.tsx + public/sw.js)
  // rather than via a bundler plugin, to keep the build simple and phone-editable.
};

module.exports = nextConfig;

module.exports = {
  plugins: {
    tailwindcss: {},
    autoprefixer: {},
  },
};

import type { Config } from "tailwindcss";

/**
 * Design tokens — foundation only (Stage 1).
 * Full component library is built out from Stage 6 onward.
 *
 * Palette rationale: deep indigo (#3730E0) as the single confident accent —
 * signals "AI" without leaning on the generic violet-gradient SaaS default;
 * paired with a warm amber (#F5A623) reserved for upgrade/CTA moments only,
 * so it stays meaningful instead of decorative. Neutral scale is a true
 * near-black/near-white, not tinted, per the design system rationale in
 * /config/design-tokens.md.
 */
const config: Config = {
  darkMode: ["class"],
  content: [
    "./app/**/*.{ts,tsx}",
    "./components/**/*.{ts,tsx}",
  ],
  theme: {
    extend: {
      colors: {
        ink: {
          950: "#0E0F12",
          800: "#23262E",
          600: "#4B4F58",
          400: "#8A8E96",
          200: "#D8DAdE",
          50: "#F7F7F8",
        },
        accent: {
          DEFAULT: "#3730E0",
          hover: "#2C24B8",
          subtle: "#EEEDFC",
        },
        upgrade: {
          DEFAULT: "#F5A623",
          hover: "#D8901A",
          subtle: "#FDF3E1",
        },
        success: "#1E9E6B",
        danger: "#D64545",
      },
      fontFamily: {
        sans: ["var(--font-sans)", "system-ui", "sans-serif"],
        display: ["var(--font-display)", "system-ui", "sans-serif"],
      },
      borderRadius: {
        sm: "6px",
        md: "10px",
        lg: "16px",
      },
      spacing: {
        18: "4.5rem",
      },
    },
  },
  plugins: [],
};

export default config;

