import type { Metadata, Viewport } from "next";
import "./globals.css";
import { AppProviders } from "@/components/providers/AppProviders";

export const metadata: Metadata = {
  title: "AI Marketing Workspace",
  description:
    "AI-powered marketing tools for small businesses — ads, emails and social posts generated from one company profile.",
  manifest: "/manifest.json",
  appleWebApp: {
    capable: true,
    statusBarStyle: "default",
    title: "AI Marketing Workspace",
  },
};

export const viewport: Viewport = {
  width: "device-width",
  initialScale: 1,
  themeColor: "#3730E0",
};

export default function RootLayout({
  children,
}: {
  children: React.ReactNode;
}) {
  return (
    <html lang="en">
      <body>
        <AppProviders>{children}</AppProviders>
        {/* Service worker registration — foundation only, no offline logic yet (Stage 1 scope). */}
        <script
          dangerouslySetInnerHTML={{
            __html: `
              if ('serviceWorker' in navigator) {
                window.addEventListener('load', () => {
                  navigator.serviceWorker.register('/sw.js').catch(() => {});
                });
              }
            `,
          }}
        />
      </body>
    </html>
  );
}

import Link from "next/link";

export default function LandingPage() {
  // Placeholder landing copy/layout — full guest landing redesign is a
  // later, dedicated stage (see Stage 6/7 scope notes). Only the /tools
  // link is new this stage: the Tools Gallery needs to be reachable from
  // somewhere.
  return (
    <main className="flex min-h-screen flex-col items-center justify-center gap-3 p-8">
      <h1 className="font-display text-2xl font-semibold">
        AI Marketing Workspace
      </h1>
      <p className="text-ink-600">Project scaffold — Stage 7 (Tools Gallery).</p>
      <div className="flex gap-3 text-sm">
        <Link href="/tools" className="text-accent hover:underline">
          Browse tools
        </Link>
        <Link href="/login" className="text-accent hover:underline">
          Sign in
        </Link>
        <Link href="/register" className="text-accent hover:underline">
          Create account
        </Link>
      </div>
    </main>
  );
}

import { requireUser } from "@/lib/supabase/auth";

/**
 * Defense-in-depth auth gate for Dashboard / Company Profile / History /
 * Billing. Middleware already redirects unauthenticated requests before
 * they get here (see root middleware.ts) — this second check is what
 * guarantees no protected page can ever render for a logged-out request
 * even if middleware is bypassed or its matcher is edited incorrectly
 * later.
 */
export default async function AuthedLayout({
  children,
}: {
  children: React.ReactNode;
}) {
  await requireUser();
  return <>{children}</>;
}

"use client";

import { useEffect } from "react";
import { Button } from "@/components/ui/Button";

export default function DashboardError({
  error,
  reset,
}: {
  error: Error & { digest?: string };
  reset: () => void;
}) {
  useEffect(() => {
    console.error("[dashboard]", error);
  }, [error]);

  return (
    <main className="mx-auto max-w-2xl space-y-4 p-6">
      <div className="rounded-md border border-danger p-8 text-center text-sm text-danger">
        Couldn&apos;t load your dashboard right now. Please try again shortly.
      </div>
      <Button variant="secondary" onClick={reset}>
        Try again
      </Button>
    </main>
  );
}

/**
 * Inline, not a separate LoadingState component: the existing
 * Tools/Templates galleries (Stage 7/10) each have their own
 * near-identical LoadingState/ErrorState pair already — a third and
 * fourth pair here would compound a duplication this stage's brief asks
 * to flag, not add to (see Stage 13 audit §4). One line of markup with no
 * other consumer doesn't earn a file of its own.
 */
export default function DashboardLoading() {
  return (
    <main className="mx-auto max-w-2xl p-6">
      <div className="rounded-md border border-ink-200 p-8 text-center text-sm text-ink-600">
        Loading dashboard…
      </div>
    </main>
  );
}

import { requireUser } from "@/lib/supabase/auth";
import { createClient } from "@/lib/supabase/server";
import { resolvePlanLimits } from "@/lib/generation/plan";
import { currentMonthPeriod } from "@/lib/generation/period";
import { UsageCard } from "@/components/usage/UsageCard";
import { SignOutButton } from "@/components/auth/SignOutButton";

/**
 * Reuses `resolvePlanLimits` (Stage 5) unchanged — this page's entire
 * plan/limit knowledge comes from calling it, not from re-deriving
 * anything about plans here. The generations-used count is read directly
 * from `usage_counters` via the existing user-scoped client: that table
 * already has a `select` RLS policy for the owning user (migration 0007,
 * written with exactly this kind of read in mind — "a usage indicator...
 * can read this directly without a dedicated API route"), so no new
 * access path is created. Deliberately not calling `checkUsage()`
 * (Stage 5): that function needs the admin client and answers a
 * different question — "may this specific tool run right now" — not "how
 * much has been used this period," which is what this page displays.
 *
 * `SignOutButton` (Stage 2) is rendered here for the first time — this
 * is the page Stage 9's audit named as where it belonged once a stage
 * "naturally starts working with Dashboard." Stage 13 is that stage.
 */
export default async function DashboardPage() {
  const user = await requireUser();
  const supabase = createClient();

  const planLimits = await resolvePlanLimits(supabase, { type: "user", userId: user.id });
  const period = currentMonthPeriod();

  const { data: usage } = await supabase
    .from("usage_counters")
    .select("generations_count")
    .eq("user_id", user.id)
    .eq("period_start", period.start)
    .maybeSingle();

  const used = usage?.generations_count ?? 0;

  return (
    <main className="mx-auto max-w-2xl space-y-6 p-6">
      <div className="flex items-center justify-between">
        <h1 className="font-display text-xl font-semibold text-ink-950">Dashboard</h1>
        <SignOutButton />
      </div>
      <UsageCard planSlug={planLimits.planSlug} used={used} limit={planLimits.maxGenerationsPerMonth} />
    </main>
  );
}

