import Link from "next/link";
import { requireUser } from "@/lib/supabase/auth";
import { createClient } from "@/lib/supabase/server";
import { HistoryItem } from "@/components/history/HistoryItem";

const PAGE_SIZE = 10;

/**
 * Direct query against `generations`, same access pattern as every other
 * (auth) page (profile, dashboard, settings/billing) — RLS's existing
 * `auth.uid() = user_id` select policy (migration 0008) is the only gate
 * needed; no new policy, no admin client, no API route. `user_id` is
 * always the filter (never `guest_session_id`): this page is under the
 * `(auth)` group, which only ever serves signed-in requests, and guest
 * generations are reassigned to `user_id` on merge (Stage 11) before a
 * person could ever reach here — no guest-specific branch to write.
 *
 * Joins `tools(name)`/`templates(name)` in the one query rather than
 * calling `resolveTool()`/`resolveTemplate()` per row: those functions
 * take a slug, not the `tool_id`/`template_id` this table actually
 * stores, and calling either per row would mean N+1 queries for what a
 * single embedded select already answers in one round trip — the same
 * reasoning Stage 10 used for lib/templates/catalog.ts's `listTemplates()`
 * over reusing the pipeline's single-row resolvers.
 *
 * Pagination: offset-based via `?page=`, the same "read an optional
 * searchParams prop" pattern already used for `?template=` (Stage 10) —
 * no cursor, no total count. Fetches PAGE_SIZE + 1 rows and checks
 * whether the extra one came back to decide if a "Next" link is needed,
 * rather than a separate COUNT(*) query — minimal, not built for a scale
 * this project doesn't have yet (first pagination in the project; no
 * existing mechanism to extend, per the pre-implementation check in this
 * stage's audit).
 */
export default async function HistoryPage({
  searchParams,
}: {
  searchParams: { page?: string };
}) {
  const user = await requireUser();
  const supabase = createClient();

  const page = Math.max(1, Number.parseInt(searchParams.page ?? "1", 10) || 1);
  const offset = (page - 1) * PAGE_SIZE;

  const { data } = await supabase
    .from("generations")
    .select("id, output, created_at, tools(name), templates(name)")
    .eq("user_id", user.id)
    .order("created_at", { ascending: false })
    .range(offset, offset + PAGE_SIZE);

  const rows = data ?? [];
  const hasNextPage = rows.length > PAGE_SIZE;
  const generations = rows.slice(0, PAGE_SIZE).map((row) => {
    // Cast, not inferred — database.types.ts is hand-written and doesn't
    // carry the `Relationships` metadata supabase-js uses to type
    // embedded selects precisely (same caveat as lib/generation/plan.ts,
    // Stage 5, and lib/templates/catalog.ts, Stage 10).
    const tool = row.tools as unknown as { name: string } | { name: string }[] | null;
    const template = row.templates as unknown as { name: string } | { name: string }[] | null;
    const toolRow = Array.isArray(tool) ? tool[0] : tool;
    const templateRow = Array.isArray(template) ? template[0] : template;

    return {
      id: row.id,
      output: row.output,
      createdAt: row.created_at,
      toolName: toolRow?.name ?? "Unknown tool",
      templateName: templateRow?.name ?? null,
    };
  });

  return (
    <main className="mx-auto max-w-2xl space-y-6 p-6">
      <h1 className="font-display text-xl font-semibold text-ink-950">History</h1>

      {generations.length === 0 ? (
        <div className="rounded-md border border-dashed border-ink-200 p-8 text-center text-sm text-ink-600">
          No generations yet — results you create will show up here.
        </div>
      ) : (
        <div className="space-y-3">
          {generations.map((generation) => (
            <HistoryItem key={generation.id} generation={generation} />
          ))}
        </div>
      )}

      {(page > 1 || hasNextPage) && (
        <div className="flex items-center justify-between text-sm">
          {page > 1 ? (
            <Link href={`/history?page=${page - 1}`} className="text-accent hover:underline">
              ← Previous
            </Link>
          ) : (
            <span />
          )}
          {hasNextPage && (
            <Link href={`/history?page=${page + 1}`} className="text-accent hover:underline">
              Next →
            </Link>
          )}
        </div>
      )}
    </main>
  );
}

import { requireUser } from "@/lib/supabase/auth";
import { createClient } from "@/lib/supabase/server";

/**
 * Read-only detail view — no form, no regenerate action, nothing that
 * could be mistaken for reopening ToolRunner. Part 3 of this stage's
 * brief requires checking whether a "restore a generation into the
 * editor" mechanism already exists before building anything like it: it
 * doesn't (ToolRunner has no "load existing generation" mode, no route
 * carries a generation's saved input_params back into a form) — so none
 * is built here. This page only shows what was already saved.
 *
 * Scoped to the owner by the same RLS select policy the list page relies
 * on (migration 0008, `auth.uid() = user_id`) — a generation that
 * doesn't exist and one that belongs to someone else are indistinguishable
 * here, both resolve to `null`, same unified treatment as
 * app/(guest)/tools/[slug]/page.tsx (Stage 8) uses for "inactive" vs
 * "nonexistent" tools.
 *
 * No copy-to-clipboard action: that needs a Client Component, and
 * nothing about "view a saved result" requires one — the text is
 * selectable natively. Considered and left out rather than added for
 * parity with ToolRunner's result panel, which Stage 14 doesn't ask for.
 */
export default async function HistoryDetailPage({ params }: { params: { id: string } }) {
  const user = await requireUser();
  const supabase = createClient();

  const { data } = await supabase
    .from("generations")
    .select("id, output, created_at, tools(name), templates(name)")
    .eq("id", params.id)
    .eq("user_id", user.id)
    .maybeSingle();

  if (!data) {
    return (
      <main className="p-8">
        <p className="text-ink-600">This generation isn&apos;t available.</p>
      </main>
    );
  }

  // Cast, not inferred — same caveat as the list page and every other
  // embedded-select site in this project (Stage 5/8/10/14).
  const tool = data.tools as unknown as { name: string } | { name: string }[] | null;
  const template = data.templates as unknown as { name: string } | { name: string }[] | null;
  const toolRow = Array.isArray(tool) ? tool[0] : tool;
  const templateRow = Array.isArray(template) ? template[0] : template;

  return (
    <main className="mx-auto max-w-2xl space-y-4 p-6">
      <div className="space-y-1">
        <h1 className="font-display text-xl font-semibold text-ink-950">
          {toolRow?.name ?? "Unknown tool"}
        </h1>
        <div className="flex items-center gap-2 text-xs text-ink-600">
          <time dateTime={data.created_at}>{new Date(data.created_at).toLocaleString()}</time>
          {templateRow?.name && (
            <span className="rounded-sm bg-accent-subtle px-2 py-0.5 text-accent">
              {templateRow.name}
            </span>
          )}
        </div>
      </div>
      <p className="whitespace-pre-wrap text-sm text-ink-950">{data.output || "(empty result)"}</p>
    </main>
  );
}

"use server";

import { z } from "zod";
import { revalidatePath } from "next/cache";
import { requireUser } from "@/lib/supabase/auth";
import { createClient } from "@/lib/supabase/server";

/**
 * The only validation layer for this form — no parallel check in the
 * client component, no second schema anywhere else. The client component
 * relies on native HTML constraints (`required`, `maxLength`) purely for
 * immediate typing feedback; the authoritative check, the one that can't
 * be bypassed, is this one, same principle as every other write path in
 * the project (Stage 5's /api/generate, Stage 6's ToolRunner client-side
 * required-field check being explicitly non-authoritative).
 *
 * Field set and constraints mirror `GuestCompanyProfileDraft`
 * (lib/guest-session/types.ts) — the same six fields Stage 11's merge
 * already writes into this same table. Not reused directly as a type
 * here because that interface has no length limits (it was never meant
 * to gate a write, only to shape a draft) — this schema is the first
 * place those fields get real, enforced constraints, which is new to
 * Stage 12 by necessity (nothing before this wrote to company_profiles
 * from untrusted form input).
 */
const CompanyProfileSchema = z.object({
  id: z.string().uuid().optional(),
  name: z.string().trim().min(1, "Company name is required.").max(200),
  niche: z.string().trim().max(200).optional(),
  toneOfVoice: z.string().trim().max(200).optional(),
  targetAudience: z.string().trim().max(500).optional(),
  usp: z.string().trim().max(500).optional(),
  websiteUrl: z.string().trim().max(300).optional(),
});

export interface CompanyProfileFormState {
  error: string | null;
  success: boolean;
}

function emptyToUndefined(value: FormDataEntryValue | null): string | undefined {
  const str = typeof value === "string" ? value.trim() : "";
  return str === "" ? undefined : str;
}

/**
 * Create-or-update in one action, branching on whether the form carried
 * an existing profile's `id` (set by the page from its own read — see
 * page.tsx) — not on a separate "does a profile exist" lookup here, which
 * would just be re-deriving what the page already determined moments
 * earlier. Targets the update by `id`, not by `user_id`: `company_profiles`
 * deliberately allows more than one row per user (Stage 3, for future
 * agency use) — updating by `user_id` alone would silently overwrite
 * every profile the user has, not just the one this form is editing.
 * RLS (`auth.uid() = user_id` on both the update's USING and the
 * insert's WITH CHECK, migration 0004) is the backstop even if `id` were
 * tampered with client-side — it scopes both paths to rows this user
 * actually owns regardless.
 */
export async function saveCompanyProfile(
  _prevState: CompanyProfileFormState,
  formData: FormData,
): Promise<CompanyProfileFormState> {
  const user = await requireUser();

  const parsed = CompanyProfileSchema.safeParse({
    id: emptyToUndefined(formData.get("id")),
    name: emptyToUndefined(formData.get("name")) ?? "",
    niche: emptyToUndefined(formData.get("niche")),
    toneOfVoice: emptyToUndefined(formData.get("toneOfVoice")),
    targetAudience: emptyToUndefined(formData.get("targetAudience")),
    usp: emptyToUndefined(formData.get("usp")),
    websiteUrl: emptyToUndefined(formData.get("websiteUrl")),
  });

  if (!parsed.success) {
    return { error: parsed.error.issues[0]?.message ?? "Invalid input.", success: false };
  }

  const supabase = createClient();
  const { id, ...fields } = parsed.data;

  const row = {
    user_id: user.id,
    name: fields.name,
    niche: fields.niche ?? null,
    tone_of_voice: fields.toneOfVoice ?? null,
    target_audience: fields.targetAudience ?? null,
    usp: fields.usp ?? null,
    website_url: fields.websiteUrl ?? null,
  };

  const { error } = id
    ? await supabase.from("company_profiles").update(row).eq("id", id)
    : await supabase.from("company_profiles").insert(row);

  if (error) {
    console.error("[profile] save failed:", error.message);
    return { error: "Something went wrong saving your profile. Please try again.", success: false };
  }

  // First mutation of Server Component-displayed data via a Server Action
  // that doesn't also redirect() (login/register, Stage 2, redirect —
  // which forces a fresh render on its own; this form stays on the page).
  // Without this, a reload right after saving could show stale data, and
  // — more importantly for correctness — the next save wouldn't yet see
  // an `id` from a fresh read if the user never navigates away.
  revalidatePath("/profile");

  return { error: null, success: true };
}

