import { createClient } from "@/lib/supabase/server";
import { resolveTool, resolveTemplate, resolveDefaultTemplate } from "@/lib/generation/catalog";
import { parseToolConfigSchema } from "@/lib/tool-config/validate";
import { ToolRunner } from "@/components/tools/ToolRunner";

/**
 * Reuses Stage 5's `resolveTool` (lib/generation/catalog.ts) rather than
 * re-querying `tools` here — same lookup /api/generate already relies on,
 * including the property this page depends on just as much: an inactive
 * tool and a nonexistent slug resolve identically (both `null`), because
 * the `tools` RLS policy already filters to `is_active = true`. One
 * lookup implementation, two callers.
 *
 * Template resolution (Stage 8, extended Stage 10): an explicit
 * `?template=` query param — as the Templates Library's TemplateCard now
 * links with — takes a specific template via `resolveTemplate`, the same
 * function /api/generate already uses; with no param, this falls back to
 * `resolveDefaultTemplate` exactly as it did before Stage 10 existed. An
 * invalid/stale `?template=` (wrong tool, deleted template) resolves to
 * `null` rather than silently substituting the default — a broken link
 * degrades to the tool's generic no-template prompt (ToolRunner's
 * existing, Stage 5-established fallback), not to different content than
 * what the link implied.
 */
export default async function ToolPage({
  params,
  searchParams,
}: {
  params: { slug: string };
  searchParams: { template?: string };
}) {
  const supabase = createClient();
  const tool = await resolveTool(supabase, params.slug);

  if (!tool) {
    return (
      <main className="p-8">
        <p className="text-ink-600">This tool isn&apos;t available.</p>
      </main>
    );
  }

  const template = searchParams.template
    ? await resolveTemplate(supabase, searchParams.template, tool.id)
    : await resolveDefaultTemplate(supabase, tool.id);
  const schema = parseToolConfigSchema(tool.configSchema);

  return (
    <main className="mx-auto max-w-2xl space-y-6 p-6">
      <h1 className="font-display text-xl font-semibold text-ink-950">{tool.name}</h1>
      <ToolRunner
        tool={{ slug: tool.slug, name: tool.name }}
        templateSlug={template?.slug}
        schema={schema}
      />
    </main>
  );
}

import { NextResponse } from "next/server";
import { parseGenerateRequest } from "@/lib/generation/validate";
import { runGeneration } from "@/lib/generation/pipeline";
import { GenerationError } from "@/lib/generation/errors";
import { AIProviderError, type AIProviderErrorKind } from "@/lib/ai-provider";

/**
 * Core Generate Pipeline entry point. This route is deliberately thin: it
 * parses the request, calls `runGeneration`, and maps whatever comes back
 * (success, GenerationError, or AIProviderError) to an HTTP response.
 * The actual pipeline — identity, tool/template lookup, plan limits,
 * usage, company context, prompt assembly, the Gateway call, persistence,
 * usage increment — lives in lib/generation/pipeline.ts, not here, so
 * that logic is testable and reusable independent of the HTTP layer.
 */
export async function POST(request: Request) {
  try {
    const body = await parseGenerateRequest(request);
    const result = await runGeneration(body);
    return NextResponse.json(result);
  } catch (error) {
    return toErrorResponse(error);
  }
}

/**
 * Every branch here returns a message safe to show a real user — no
 * provider error text, no DB error text, no stack traces. Anything with
 * internal detail worth knowing was already `console.error`'d where it
 * happened (see save.ts, identity.ts) before reaching this point.
 */
function toErrorResponse(error: unknown): NextResponse {
  if (error instanceof GenerationError) {
    return NextResponse.json(
      { error: { code: error.code, message: error.message } },
      { status: error.httpStatus },
    );
  }

  if (error instanceof AIProviderError) {
    const { status, message } = mapProviderError(error.kind);
    console.error(`[AIProviderError:${error.provider}:${error.kind}]`, error.message);
    return NextResponse.json({ error: { code: "ai_provider_error", message } }, { status });
  }

  console.error("[api/generate] unhandled error:", error);
  return NextResponse.json(
    { error: { code: "internal_error", message: "Something went wrong. Please try again." } },
    { status: 500 },
  );
}

function mapProviderError(kind: AIProviderErrorKind): { status: number; message: string } {
  switch (kind) {
    case "rate_limited":
      return { status: 503, message: "The AI provider is busy right now. Please try again shortly." };
    case "overloaded":
      return { status: 503, message: "The AI provider is temporarily unavailable. Please try again shortly." };
    case "network":
      return { status: 503, message: "Couldn't reach the AI provider. Please try again shortly." };
    case "timeout":
      return { status: 504, message: "The request took too long. Please try again." };
    // configuration / authentication / invalid_request / not_implemented /
    // unknown are all *our* bugs or misconfiguration, never the caller's —
    // same generic message and status for all of them so nothing about
    // our setup is distinguishable from the outside.
    default:
      return { status: 500, message: "Something went wrong generating your content. Please try again." };
  }
}

import { NextResponse } from "next/server";
import { createClient } from "@/lib/supabase/server";
import { createAdminClient } from "@/lib/supabase/admin";
import type { GuestCompanyProfileDraft } from "@/lib/guest-session/types";

/**
 * Guest → User merge endpoint. Stage 2 built the auth check, request
 * validation, and the response contract the client (AuthSyncListener)
 * already codes against (`status === "merged"` clears the guest token —
 * nothing about that contract changes here, see below). Stage 11 fills
 * in the one thing Stage 2 explicitly deferred: the actual data move.
 *
 * Per migration 0008's own comment (written in Stage 3, describing this
 * exact stage before it existed): "flipping guest_session_id to null and
 * setting user_id on existing rows is enough, nothing needs to move" —
 * this is a metadata UPDATE, not a data copy. That design decision is
 * being executed here, not invented here.
 */

interface MergeRequestBody {
  guestSessionToken?: string;
}

export async function POST(request: Request) {
  const supabase = createClient();
  const {
    data: { user },
  } = await supabase.auth.getUser();

  if (!user) {
    return NextResponse.json({ error: "unauthorized" }, { status: 401 });
  }

  let body: MergeRequestBody;
  try {
    body = await request.json();
  } catch {
    return NextResponse.json({ error: "invalid_json" }, { status: 400 });
  }

  if (!body.guestSessionToken || typeof body.guestSessionToken !== "string") {
    return NextResponse.json(
      { error: "missing_guest_session_token" },
      { status: 400 },
    );
  }

  const admin = createAdminClient();

  // guest_sessions has no client-facing read policy at all (migration
  // 0005) — the admin client is the only way to resolve a token to a row,
  // same reasoning as lib/generation/identity.ts's lazy creation of this
  // same table.
  const { data: guestSession } = await admin
    .from("guest_sessions")
    .select("id, company_profile_draft")
    .eq("session_token", body.guestSessionToken)
    .maybeSingle();

  // No row for this token (never used to generate anything, or already
  // merged by an earlier request — this endpoint is idempotent, see
  // below) — nothing to move, but the token itself is now meaningless
  // either way. Reporting "merged" here isn't inaccurate framing: the
  // client's only contract with this status is "stop holding onto this
  // token" (AuthSyncListener.tsx), which is exactly correct in this case
  // too. Introducing a distinct status for this case would mean teaching
  // the client a new state for no behavioral difference — the opposite
  // of the minimal, reuse-first change this stage calls for.
  if (!guestSession) {
    return NextResponse.json({ status: "merged", generationsMerged: 0, companyProfileCreated: false });
  }

  // The reassignment itself: one UPDATE, admin client. The authenticated
  // user's own RLS-scoped client cannot do this — `generations`' update
  // policy (migration 0008) is `auth.uid() = user_id`, and these rows
  // currently have `user_id = null`, which never satisfies that check.
  // Bypassing RLS here is exactly what lib/supabase/admin.ts exists for.
  const { data: reassigned, error: reassignError } = await admin
    .from("generations")
    .update({ user_id: user.id, guest_session_id: null })
    .eq("guest_session_id", guestSession.id)
    .select("id");

  if (reassignError) {
    // A real failure here — unlike a save failure in the generation
    // pipeline (Stage 5), there's no already-delivered result to protect
    // by degrading gracefully. Reporting an error lets the client leave
    // the guest token in place (AuthSyncListener's existing behavior for
    // any non-"merged" response) so a retry on the next sign-in can pick
    // this back up rather than silently losing the data.
    console.error("[session/merge] failed to reassign generations:", reassignError.message);
    return NextResponse.json({ error: "merge_failed" }, { status: 500 });
  }

  const companyProfileCreated = await maybeCreateCompanyProfileFromDraft(
    supabase,
    user.id,
    guestSession.company_profile_draft as GuestCompanyProfileDraft | null,
  );

  return NextResponse.json({
    status: "merged",
    generationsMerged: reassigned?.length ?? 0,
    companyProfileCreated,
  });
}

/**
 * Only creates a profile when there's a `name` to create it with —
 * `company_profiles.name` is `not null` (migration 0004), so a draft with
 * no name can't become a valid row regardless of what else it has. Only
 * runs when the user has zero existing profiles: a returning user who
 * already set one up (e.g. from a previous session on another device)
 * should not get a second, draft-derived one silently appended —
 * `company_profiles` allows multiple rows per user by design (Stage 3,
 * for future agency use), but that's a deliberate choice a user makes,
 * not something this endpoint should do on their behalf.
 *
 * Uses the caller's own RLS-scoped client, not admin: this INSERT is for
 * a row owned by `user.id`, and `company_profiles`' authenticated INSERT
 * policy (`auth.uid() = user_id`) already permits it — no privileged
 * access needed, same reasoning Stage 5's saveGeneration() used to pick
 * between the two clients for authenticated writes.
 */
async function maybeCreateCompanyProfileFromDraft(
  supabase: ReturnType<typeof createClient>,
  userId: string,
  draft: GuestCompanyProfileDraft | null,
): Promise<boolean> {
  if (!draft?.name) return false;

  const { count } = await supabase
    .from("company_profiles")
    .select("id", { count: "exact", head: true })
    .eq("user_id", userId);

  if (count && count > 0) return false;

  const { error } = await supabase.from("company_profiles").insert({
    user_id: userId,
    name: draft.name,
    niche: draft.niche,
    tone_of_voice: draft.toneOfVoice,
    target_audience: draft.targetAudience,
    usp: draft.usp,
    website_url: draft.websiteUrl,
  });

  if (error) {
    // Not fatal to the merge response: generations (the primary asset)
    // already moved successfully by this point. Same "don't discard a
    // real result over a secondary write failing" reasoning as Stage 5's
    // saveGeneration().
    console.error("[session/merge] failed to create company profile from draft:", error.message);
    return false;
  }

  return true;
}

import { NextResponse, type NextRequest } from "next/server";
import { createClient } from "@/lib/supabase/server";

/**
 * Supabase email-confirmation / magic-link landing point. Exchanges the
 * one-time `code` query param for a real session cookie, then sends the
 * user on to the dashboard.
 */
export async function GET(request: NextRequest) {
  const { searchParams, origin } = new URL(request.url);
  const code = searchParams.get("code");

  if (code) {
    const supabase = createClient();
    await supabase.auth.exchangeCodeForSession(code);
  }

  return NextResponse.redirect(`${origin}/dashboard`);
}

"use server";

import { redirect } from "next/navigation";
import { createClient } from "@/lib/supabase/server";

export interface AuthFormState {
  error: string | null;
}

export async function signIn(
  _prevState: AuthFormState,
  formData: FormData,
): Promise<AuthFormState> {
  const email = String(formData.get("email") ?? "");
  const password = String(formData.get("password") ?? "");
  const next = String(formData.get("next") ?? "/dashboard");

  if (!email || !password) {
    return { error: "Enter your email and password." };
  }

  const supabase = createClient();
  const { error } = await supabase.auth.signInWithPassword({ email, password });

  if (error) {
    return { error: error.message };
  }

  // Guest → user merge is triggered client-side (components/auth/AuthSyncListener.tsx)
  // via Supabase's onAuthStateChange, not here — a server action has no
  // access to the guest token sitting in the browser's localStorage.
  redirect(next);
}

