import type { ReactNode } from "react";
import { GuestSessionProvider } from "@/lib/guest-session/context";
import { AuthSyncListener } from "@/components/auth/AuthSyncListener";

/**
 * Single mount point for all client-side, app-wide providers. Root
 * layout.tsx (a Server Component) renders this once so future providers
 * (theme, toasts, etc.) have one obvious place to be added rather than
 * accumulating ad hoc wrappers in layout.tsx itself.
 */
export function AppProviders({ children }: { children: ReactNode }) {
  return (
    <GuestSessionProvider>
      <AuthSyncListener />
      {children}
    </GuestSessionProvider>
  );
}

/** Independent from components/tools/gallery/EmptyState.tsx: that
 *  component's `reason` union type is literally typed to
 *  "no-tools" | "no-results" — widening it to also accept a templates
 *  reason would mean editing an already-shipped Stage 7 file with no
 *  objective need (the component's own logic isn't shared, just the
 *  three-line JSX shape is coincidentally similar). */
export function EmptyState({ reason }: { reason: "no-templates" | "no-results" }) {
  const message =
    reason === "no-templates"
      ? "No templates are available yet — check back soon."
      : "No templates match your search or filter.";

  return (
    <div className="rounded-md border border-dashed border-ink-200 p-8 text-center text-sm text-ink-600">
      {message}
    </div>
  );
}

/** Independent from components/tools/gallery/ErrorState.tsx for the same
 *  reason as LoadingState.tsx above (hardcoded "tools" text). Rendered
 *  by app/(guest)/templates/error.tsx when listTemplates() throws a
 *  TemplateCatalogError — message stays generic on purpose, same
 *  reasoning as every other error boundary in this project (Stage 5's
 *  route.ts, Stage 7's tools ErrorState). */
export function ErrorState() {
  return (
    <div className="rounded-md border border-danger p-8 text-center text-sm text-danger">
      Couldn&apos;t load templates right now. Please try again shortly.
    </div>
  );
}

/** Independent from components/tools/gallery/LoadingState.tsx — that
 *  component's text is hardcoded to "Loading tools…", not a prop, so
 *  reusing it here would show the wrong word. Used by
 *  app/(guest)/templates/loading.tsx. */
export function LoadingState() {
  return (
    <div className="rounded-md border border-ink-200 p-8 text-center text-sm text-ink-600">
      Loading templates…
    </div>
  );
}

