"use client";

import { useMemo, useState } from "react";
import type { TemplateListItem } from "@/lib/templates/types";
import { queryTemplates, deriveCategories } from "@/lib/templates/query";
import { SearchBar } from "@/components/tools/gallery/SearchBar";
import { CategoryFilter } from "@/components/tools/gallery/CategoryFilter";
import { TemplateGrid } from "./TemplateGrid";
import { EmptyState } from "./EmptyState";

/**
 * Same shape as components/tools/gallery/ToolGallery.tsx (Stage 7): owns
 * search/category state, derives everything shown from `templates` via
 * pure functions, never a hand-written list. Reuses SearchBar and
 * CategoryFilter directly (both already fully generic — see this stage's
 * audit for why SearchBar gained two optional props to make that true
 * without changing its existing caller's behavior); TemplateGrid/
 * TemplateCard/EmptyState are independent from their tools/ counterparts
 * because those render a different item shape and carry
 * tools-specific text, not because sharing was rejected in general.
 */
export function TemplateGallery({ templates }: { templates: TemplateListItem[] }) {
  const [search, setSearch] = useState("");
  const [category, setCategory] = useState<string | null>(null);

  const categories = useMemo(() => deriveCategories(templates), [templates]);
  const filtered = useMemo(
    () => queryTemplates(templates, { search, category, sortBy: "name" }),
    [templates, search, category],
  );

  return (
    <div className="space-y-4">
      <div className="flex flex-col gap-3 sm:flex-row sm:items-center">
        <SearchBar
          value={search}
          onChange={setSearch}
          placeholder="Search templates…"
          ariaLabel="Search templates"
        />
        {categories.length > 0 && (
          <CategoryFilter categories={categories} value={category} onChange={setCategory} />
        )}
      </div>

      {templates.length === 0 ? (
        <EmptyState reason="no-templates" />
      ) : filtered.length === 0 ? (
        <EmptyState reason="no-results" />
      ) : (
        <TemplateGrid templates={filtered} />
      )}
    </div>
  );
}

import type { TemplateListItem } from "@/lib/templates/types";
import { TemplateCard } from "./TemplateCard";

/** Pure layout, same shape as components/tools/gallery/ToolGrid.tsx
 *  (Stage 7) — not shared, for the same reason lib/templates/query.ts
 *  isn't: the two render different item shapes and are free to diverge. */
export function TemplateGrid({ templates }: { templates: TemplateListItem[] }) {
  return (
    <div className="grid grid-cols-1 gap-4 sm:grid-cols-2 lg:grid-cols-3">
      {templates.map((template) => (
        <TemplateCard key={template.slug} template={template} />
      ))}
    </div>
  );
}

"use client";

import { FIELD_COMPONENTS } from "./fields";
import type { FieldComponentProps } from "./fields/types";

/**
 * ToolRunner's only dependency on "what field types exist" — it renders
 * whatever `schema.fields` contains by looking each one up in the
 * registry. Nothing here knows about `text` vs `select` vs any other
 * specific type; that knowledge lives entirely in fields/index.ts.
 *
 * An unrecognized `field.type` (a newer config_schema running against an
 * older deployed frontend, or a typo written by hand in the SQL editor)
 * degrades to an inline message instead of crashing the whole form — the
 * same "fail one field, not the page" instinct as
 * lib/tool-config/validate.ts failing an entire malformed schema down to
 * an empty one.
 */
export function FieldRenderer({ field, value, onChange, error }: FieldComponentProps) {
  const Component = FIELD_COMPONENTS[field.type];

  if (!Component) {
    return (
      <p className="text-sm text-danger">
        Unsupported field type &quot;{field.type}&quot; for &quot;{field.label}&quot;.
      </p>
    );
  }

  return <Component field={field} value={value} onChange={onChange} error={error} />;
}

"use client";

import { useState, type FormEvent } from "react";
import { useGuestSession } from "@/lib/guest-session/context";
import { Button } from "@/components/ui/Button";
import { Card } from "@/components/ui/Card";
import { FieldRenderer } from "./FieldRenderer";
import { buildInitialValues } from "@/lib/tool-config/initialValues";
import { findMissingRequiredFields } from "@/lib/tool-config/validateValues";
import type { ToolConfigSchema } from "@/lib/tool-config/schema";

export interface ToolRunnerProps {
  tool: { slug: string; name: string };
  /** Optional today (no Templates Library UI yet — Stage 10); the prop
   *  exists now purely because Stage 5's /api/generate already accepts
   *  it, so a future template picker only has to pass this down, not
   *  change ToolRunner. */
  templateSlug?: string;
  schema: ToolConfigSchema;
}

/**
 * Response shapes mirrored from Stage 5's contract
 * (lib/generation/pipeline.ts GenerateResult / app/api/generate/route.ts
 * error shape) rather than imported directly: that module chain is
 * marked `server-only` end to end (pipeline.ts → ai-provider, supabase
 * admin, etc.), so importing its types here would be importing from a
 * module Next.js would refuse to bundle for the client. Duplicating just
 * the response *shape* — not any logic — is the correct boundary, not a
 * shortcut; if the two drift, that's a contract break worth a compiler
 * error on whichever side changes.
 */
interface GenerateSuccess {
  id: string | null;
  saved: boolean;
  output: string;
  provider: string;
  model: string;
  remaining: number | "unlimited";
}
interface GenerateError {
  error: { code: string; message: string };
}

export function ToolRunner({ tool, templateSlug, schema }: ToolRunnerProps) {
  const { session } = useGuestSession();
  const [values, setValues] = useState<Record<string, unknown>>(() => buildInitialValues(schema));
  const [fieldErrors, setFieldErrors] = useState<Record<string, string>>({});
  const [submitting, setSubmitting] = useState(false);
  const [submitError, setSubmitError] = useState<string | null>(null);
  const [result, setResult] = useState<GenerateSuccess | null>(null);
  const [copied, setCopied] = useState(false);

  function setValue(name: string, value: unknown) {
    setValues((prev) => ({ ...prev, [name]: value }));
    setFieldErrors((prev) => {
      if (!(name in prev)) return prev;
      const next = { ...prev };
      delete next[name];
      return next;
    });
  }

  async function handleSubmit(event: FormEvent) {
    event.preventDefault();

    const missing = findMissingRequiredFields(schema, values);
    if (missing.length > 0) {
      setFieldErrors(Object.fromEntries(missing.map((name) => [name, "This field is required."])));
      return;
    }

    setSubmitting(true);
    setSubmitError(null);
    setResult(null);
    setCopied(false);

    try {
      const response = await fetch("/api/generate", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        // guestSessionToken is sent whenever a guest session exists,
        // regardless of whether the caller turns out to be signed in —
        // Stage 5's identity resolution checks the auth cookie first and
        // simply ignores this token for a signed-in request, so
        // ToolRunner never needs to know or care which case it's in.
        body: JSON.stringify({
          toolSlug: tool.slug,
          templateSlug,
          inputParams: values,
          guestSessionToken: session?.sessionToken,
        }),
      });

      const body = await response.json();

      if (!response.ok) {
        const errorBody = body as GenerateError;
        setSubmitError(errorBody.error?.message ?? "Something went wrong. Please try again.");
        return;
      }

      setResult(body as GenerateSuccess);
    } catch {
      setSubmitError("Network error. Please check your connection and try again.");
    } finally {
      setSubmitting(false);
    }
  }

  async function handleCopy() {
    if (!result) return;
    await navigator.clipboard.writeText(result.output);
    setCopied(true);
  }

  return (
    <div className="space-y-6">
      <form onSubmit={handleSubmit} className="space-y-4">
        {schema.fields.length === 0 ? (
          <p className="text-sm text-ink-600">This tool has no configurable inputs — just generate.</p>
        ) : (
          schema.fields.map((field) => (
            <FieldRenderer
              key={field.name}
              field={field}
              value={values[field.name]}
              onChange={(value) => setValue(field.name, value)}
              error={fieldErrors[field.name]}
            />
          ))
        )}

        {submitError && <p className="text-sm text-danger">{submitError}</p>}

        <Button type="submit" disabled={submitting}>
          {submitting ? "Generating…" : `Generate with ${tool.name}`}
        </Button>
      </form>

      {result && (
        <Card className="space-y-3">
          <div className="flex items-center justify-between gap-3">
            <h2 className="font-medium text-ink-950">Result</h2>
            <Button variant="secondary" onClick={handleCopy}>
              {copied ? "Copied" : "Copy"}
            </Button>
          </div>
          <p className="whitespace-pre-wrap text-sm text-ink-950">{result.output}</p>
          {!result.saved && (
            <p className="text-xs text-upgrade">
              This result wasn&apos;t saved to your history — copy it now if you want to keep it.
            </p>
          )}
          {result.remaining !== "unlimited" && (
            <p className="text-xs text-ink-600">{result.remaining} generations left this period.</p>
          )}
        </Card>
      )}
    </div>
  );
}

