};

import type { FieldConfig } from "@/lib/tool-config/schema";

/**
 * The one prop contract every field component implements — this is what
 * makes the registry in ./index.ts possible. A new field type only needs
 * to satisfy this shape to slot in; ToolRunner and FieldRenderer never
 * grow a case for it.
 */
export interface FieldComponentProps<TField extends FieldConfig = FieldConfig> {
  field: TField;
  value: unknown;
  onChange: (value: unknown) => void;
  error?: string;
}

"use client";

import { Select } from "@/components/ui/Select";

/** Reuses the Select primitive built for ToolRunner's SelectField (Stage 6)
 *  — a plain filter dropdown needed nothing that primitive doesn't
 *  already provide. `categories` always comes from
 *  `lib/tools/query.ts`'s `deriveCategories()`, never a hand-written list. */
export function CategoryFilter({
  categories,
  value,
  onChange,
}: {
  categories: string[];
  value: string | null;
  onChange: (value: string | null) => void;
}) {
  return (
    <Select
      value={value ?? ""}
      onChange={(e) => onChange(e.target.value === "" ? null : e.target.value)}
      aria-label="Filter by category"
      className="sm:max-w-xs"
    >
      <option value="">All categories</option>
      {categories.map((category) => (
        <option key={category} value={category}>
          {category}
        </option>
      ))}
    </Select>
  );
}

/** Same component for both cases Stage 7 asked for — an empty catalog
 *  and a search/filter with no matches — just a different message,
 *  rather than two near-identical components. */
export function EmptyState({ reason }: { reason: "no-tools" | "no-results" }) {
  const message =
    reason === "no-tools"
      ? "No tools are available yet — check back soon."
      : "No tools match your search or filter.";

  return (
    <div className="rounded-md border border-dashed border-ink-200 p-8 text-center text-sm text-ink-600">
      {message}
    </div>
  );
}

/** Rendered by app/(guest)/tools/error.tsx when listActiveTools() throws
 *  a ToolCatalogError — the message stays generic on purpose (no DB
 *  error text), same reasoning as app/api/generate/route.ts not leaking
 *  provider/DB errors to the client (Stage 5). */
export function ErrorState() {
  return (
    <div className="rounded-md border border-danger p-8 text-center text-sm text-danger">
      Couldn&apos;t load tools right now. Please try again shortly.
    </div>
  );
}

/** Deliberately plain text, not a skeleton/spinner — Stage 7 explicitly
 *  scopes out "visual design," and a skeleton loader is a design
 *  decision, not an architectural one. Used by app/(guest)/tools/loading.tsx,
 *  which Next.js renders automatically while the gallery page's data
 *  fetch is in flight. */
export function LoadingState() {
  return (
    <div className="rounded-md border border-ink-200 p-8 text-center text-sm text-ink-600">
      Loading tools…
    </div>
  );
}

