    throw new AIProviderError(
      this.name,
      "not_implemented",
      "MistralProvider is a Stage 4 stub — not yet connected to a real API.",
    );
  }
}

import "server-only";
import type { AIProvider, AIGenerateParams, AIGenerateResult } from "./types";
import { AIProviderError } from "./types";

/**
 * Openai provider stub. Implemented post-MVP when a second provider is
 * actually turned on for users (see project architecture doc, section 6).
 * Kept as a real file (not just a TODO) so the factory in index.ts can
 * already reference it and the "add a provider = one file + one config
 * line" claim is true from day one — Stage 4 connects Claude for real
 * (claude.ts) and brings every other provider up to the same error-contract
 * shape, without implementing the calls themselves.
 */
export class OpenaiProvider implements AIProvider {
  readonly name = "openai" as const;

  async generate(_params: AIGenerateParams): Promise<AIGenerateResult> {
    throw new AIProviderError(
      this.name,
      "not_implemented",
      "OpenaiProvider is a Stage 4 stub — not yet connected to a real API.",
    );
  }
}

/**
 * AI Provider Gateway — shared contract.
 *
 * Every provider (Claude, OpenAI, Gemini, Mistral, Grok, or any other
 * OpenAI-compatible API) implements this single interface. Business logic
 * (app/api/generate) only ever talks to `AIProvider`, never to a specific
 * vendor SDK — swapping or adding a provider is a config change, not a
 * rewrite of the generation pipeline.
 */

export interface AIGenerateParams {
  systemPrompt: string;
  userPrompt: string;
  model: string;
  maxTokens: number;
  temperature?: number;
  /** Defaults to a per-provider sane value if omitted (see each provider). */
  timeoutMs?: number;
  /** Lets the caller (Stage 5's /api/generate) cancel an in-flight call, e.g. on client disconnect. */
  signal?: AbortSignal;
}

export interface AITokenUsage {
  inputTokens: number;
  outputTokens: number;
}

export interface AIGenerateResult {
  text: string;
  usage: AITokenUsage;
  /** Echoes back which provider/model actually served the request, for logging in `generations`. */
  provider: AIProviderName;
  model: string;
}

export type AIProviderName =
  | "claude"
  | "openai"
  | "gemini"
  | "mistral"
  | "grok"
  | "openai-compatible";

export interface AIProvider {
  readonly name: AIProviderName;
  generate(params: AIGenerateParams): Promise<AIGenerateResult>;
}

/**
 * What went wrong, in terms the *caller* needs to act on — not which SDK
 * exception was thrown. Stage 5's usage-limit logic and error messaging
 * branch on `kind`/`retryable`, never on a provider-specific error class,
 * which is exactly what keeps that code provider-agnostic.
 *
 * - configuration   — this deployment is missing/misconfigured (no API key
 *                      set for an active provider). Not the user's fault;
 *                      not retryable.
 * - not_implemented — provider is a Stage 4 stub, not yet connected.
 * - authentication  — the provider rejected our credentials.
 * - rate_limited     — provider's own rate limit hit (distinct from this
 *                      app's plan-based usage limits, which are Stage 5).
 * - invalid_request  — malformed request (bad model name, params) — a bug,
 *                      not a transient condition.
 * - overloaded       — provider is temporarily unable to serve (5xx).
 * - network          — connection-level failure reaching the provider.
 * - timeout          — the call exceeded `timeoutMs`.
 * - unknown          — anything that doesn't map to the above.
 */
export type AIProviderErrorKind =
  | "configuration"
  | "not_implemented"
  | "authentication"
  | "rate_limited"
  | "invalid_request"
  | "overloaded"
  | "network"
  | "timeout"
  | "unknown";

const RETRYABLE_KINDS: ReadonlySet<AIProviderErrorKind> = new Set([
  "overloaded",
  "network",
  "timeout",
]);

export class AIProviderError extends Error {
  public readonly retryable: boolean;

  constructor(
    public readonly provider: AIProviderName,
    public readonly kind: AIProviderErrorKind,
    message: string,
    public readonly cause?: unknown,
  ) {
    super(`[${provider}:${kind}] ${message}`);
    this.name = "AIProviderError";
    this.retryable = RETRYABLE_KINDS.has(kind);
  }
}

import "server-only";
import type { SupabaseClient } from "@supabase/supabase-js";
import type { Database } from "@/lib/supabase/database.types";

export interface ResolvedTool {
  id: string;
  slug: string;
  name: string;
  configSchema: Record<string, unknown>;
}

export interface ResolvedTemplate {
  id: string;
  slug: string;
  name: string;
  promptTemplate: string;
  requiredFields: string[];
}

/**
 * Reads through the request-scoped client, not admin — `tools`/`templates`
 * are public-read reference tables (migration 0006), and their RLS policy
 * already filters to `is_active = true` for tools. That's not incidental:
 * it means an inactive tool and a nonexistent tool look identical here
 * (both resolve to `null`), which is exactly the behavior we want — no
 * separate "is it disabled or does it not exist" branch needed, and no
 * internal state leaked to the caller either way.
 */
export async function resolveTool(
  supabase: SupabaseClient<Database>,
  slug: string,
): Promise<ResolvedTool | null> {
  const { data } = await supabase
    .from("tools")
    .select("id, slug, name, config_schema")
    .eq("slug", slug)
    .maybeSingle();

  if (!data) return null;

  return {
    id: data.id,
    slug: data.slug,
    name: data.name,
    configSchema: (data.config_schema as Record<string, unknown>) ?? {},
  };
}

export async function resolveTemplate(
  supabase: SupabaseClient<Database>,
  slug: string,
  toolId: string,
): Promise<ResolvedTemplate | null> {
  const { data } = await supabase
    .from("templates")
    .select("id, slug, name, prompt_template, required_fields")
    .eq("slug", slug)
    .eq("tool_id", toolId)
    .maybeSingle();

  return data ? toResolvedTemplate(data) : null;
}

/**
 * Stage 8: the tool page needs *a* template to exercise the templated
 * prompt path end-to-end, but Stage 10 (Templates Library picker UI)
 * hasn't shipped yet — there's no UI for a person to choose among several
 * templates, and today there's exactly one template per active tool
 * anyway. "Oldest by created_at" is a deterministic, well-defined answer
 * for that one-row case; it stays well-defined (if not necessarily the
 * *right* choice once real UX exists) if a tool later gets more
 * templates, and Stage 10 can introduce an explicit notion of "default"
 * then, driven by whatever picker UX it actually builds — adding that
 * now would be guessing at a UI decision this stage was explicitly told
 * not to make.
 */
export async function resolveDefaultTemplate(
  supabase: SupabaseClient<Database>,
  toolId: string,
): Promise<ResolvedTemplate | null> {
  const { data } = await supabase
    .from("templates")
    .select("id, slug, name, prompt_template, required_fields")
    .eq("tool_id", toolId)
    .order("created_at", { ascending: true })
    .limit(1)
    .maybeSingle();

  return data ? toResolvedTemplate(data) : null;
}

/** Shared by resolveTemplate and resolveDefaultTemplate so the row→shape
 *  mapping exists in exactly one place — the two functions differ only in
 *  which row they select, never in how they interpret it. */
function toResolvedTemplate(row: {
  id: string;
  slug: string;
  name: string;
  prompt_template: string;
  required_fields: unknown;
}): ResolvedTemplate {
  return {
    id: row.id,
    slug: row.slug,
    name: row.name,
    promptTemplate: row.prompt_template,
    requiredFields: Array.isArray(row.required_fields)
      ? row.required_fields.filter((f): f is string => typeof f === "string")
      : [],
  };
}

import "server-only";
import type { SupabaseClient } from "@supabase/supabase-js";
import type { Database } from "@/lib/supabase/database.types";
import type { GuestCompanyProfileDraft } from "@/lib/guest-session/types";
import type { Identity } from "./identity";

/**
 * Provider-agnostic shape every tool's prompt gets built from — same shape
 * whether it came from a real `company_profiles` row or a guest's
 * localStorage-backed draft, so `lib/generation/prompt.ts` doesn't need to
 * know which one it's looking at.
 */
export type CompanyContext = GuestCompanyProfileDraft;

export interface CompanyContextResult {
  companyProfileId: string | null;
  context: CompanyContext | null;
}

/**
 * No profile is a valid, expected state — not an error. A user might
 * generate before ever completing onboarding (guest-first means "use a
 * tool" comes before "profile exists" by design, project architecture doc
 * §8), and a guest may not have filled in a draft yet either. The prompt
 * builder (Stage 5, lib/generation/prompt.ts) degrades gracefully to a
 * generic prompt when `context` is null — this function's only job is to
 * fetch what exists, not to require it.
 */
export async function resolveCompanyContext(params: {
  userClient: SupabaseClient<Database>;
  identity: Identity;
  requestedCompanyProfileId?: string;
}): Promise<CompanyContextResult> {
  if (params.identity.type === "guest") {
    return { companyProfileId: null, context: params.identity.companyProfileDraft };
  }

  let query = params.userClient
    .from("company_profiles")
    .select("id, name, niche, tone_of_voice, target_audience, usp, website_url")
    .eq("user_id", params.identity.userId);

  // RLS (migration 0004) already scopes every row to auth.uid() = user_id
  // regardless of which id is requested — a caller passing another user's
  // companyProfileId simply gets no row back, not another user's data.
  query = params.requestedCompanyProfileId
    ? query.eq("id", params.requestedCompanyProfileId)
    : query.order("updated_at", { ascending: false });

  const { data } = await query.limit(1).maybeSingle();

  if (!data) return { companyProfileId: null, context: null };

  return {
    companyProfileId: data.id,
    context: {
      name: data.name ?? undefined,
      niche: data.niche ?? undefined,
      toneOfVoice: data.tone_of_voice ?? undefined,
      targetAudience: data.target_audience ?? undefined,
      usp: data.usp ?? undefined,
      websiteUrl: data.website_url ?? undefined,
    },
  };
}

/**
 * Pipeline-level errors — distinct from `AIProviderError` (lib/ai-provider),
 * which covers failures *inside* a provider call. `GenerationError` covers
 * everything around it: bad input, no access, over a limit. The route
 * handler (app/api/generate/route.ts) is the only place that catches
 * either kind and turns it into an HTTP response — every other module
 * just throws.
 */
export class GenerationError extends Error {
  constructor(
    public readonly code: string,
    public readonly httpStatus: number,
    message: string,
  ) {
    super(message);
    this.name = "GenerationError";
  }
}

import "server-only";
import type { SupabaseClient } from "@supabase/supabase-js";
import type { Database } from "@/lib/supabase/database.types";
import { appSettings } from "@/config/settings";
import type { GuestCompanyProfileDraft } from "@/lib/guest-session/types";

export type Identity =
  | { type: "user"; userId: string }
  | { type: "guest"; guestSessionId: string; companyProfileDraft: GuestCompanyProfileDraft | null };

/**
 * The one place that decides "who is making this request" for the whole
 * generation pipeline. Every other module (plan limits, usage, company
 * context, saving the row) takes an already-resolved `Identity`, never a
 * raw user/cookie/token — this is the only function that touches auth
 * state or the guest_sessions table directly.
 *
 * Signed-in wins over a guest token if both are somehow present (e.g. a
 * stale guest token still in localStorage after Stage 2's merge trigger
 * fires) — there's no scenario where a logged-in request should be
 * evaluated as a guest.
 */
export async function resolveIdentity(params: {
  userClient: SupabaseClient<Database>;
  adminClient: SupabaseClient<Database>;
  guestSessionToken?: string;
}): Promise<Identity | null> {
  const {
    data: { user },
  } = await params.userClient.auth.getUser();

  if (user) {
    return { type: "user", userId: user.id };
  }

  if (!params.guestSessionToken) {
    return null;
  }

  return upsertGuestSession(params.adminClient, params.guestSessionToken);
}

/**
 * Stage 2 created the client-side contract for a guest session token
 * (localStorage) but nothing ever wrote the corresponding row to
 * `guest_sessions` — it had no reason to yet. This is the first code path
 * that actually needs the row to exist (to check per-guest usage against
 * it, and to attach generations to a real `guest_session_id` foreign key),
 * so it's created here, lazily, on first use — not a gap being patched
 * after the fact, but the point in the architecture where this was always
 * meant to happen (see project architecture doc §8: guest state is
 * created as the guest starts interacting, not on some earlier trigger).
 *
 * Sliding TTL: every real use extends `expires_at`, so an active guest is
 * never cut off mid-session just because their first visit was 30 days
 * ago — only genuinely abandoned sessions expire.
 */
async function upsertGuestSession(
  adminClient: SupabaseClient<Database>,
  sessionToken: string,
): Promise<Identity> {
  const newExpiresAt = new Date(
    Date.now() + appSettings.guestSessionTtlDays * 24 * 60 * 60 * 1000,
  ).toISOString();

  const { data: existing } = await adminClient
    .from("guest_sessions")
    .select("id, company_profile_draft")
    .eq("session_token", sessionToken)
    .maybeSingle();

  if (existing) {
    await adminClient
      .from("guest_sessions")
      .update({ expires_at: newExpiresAt })
      .eq("id", existing.id);

    return {
      type: "guest",
      guestSessionId: existing.id,
      companyProfileDraft:
        (existing.company_profile_draft as GuestCompanyProfileDraft | null) ?? null,
    };
  }

  const { data: created, error } = await adminClient
    .from("guest_sessions")
    .insert({ session_token: sessionToken, expires_at: newExpiresAt })
    .select("id")
    .single();

  if (error || !created) {
    // Falls through to the route's generic 500 handling — deliberately not
    // swallowed into a silent "treat as no identity" here, since that
    // would look to the caller like an invalid token rather than a real
    // server-side failure.
    throw new Error(`Failed to create guest session: ${error?.message ?? "unknown error"}`);
  }

  return { type: "guest", guestSessionId: created.id, companyProfileDraft: null };
}

/**
 * Usage tracked per calendar month (UTC) — simple, predictable, matches
 * how the Free/Pro plan copy ("500 generations/month") will read on a
 * future billing page. A rolling 30-day window would be marginally fairer
 * at the edges but harder to explain and harder to reconcile against a
 * calendar-month Stripe billing cycle later — not worth the complexity
 * this stage doesn't need yet.
 */
export interface UsagePeriod {
  start: string; // YYYY-MM-DD, matches usage_counters.period_start (date column)
  end: string; // YYYY-MM-DD, exclusive
}

export function currentMonthPeriod(now: Date = new Date()): UsagePeriod {
  const start = new Date(Date.UTC(now.getUTCFullYear(), now.getUTCMonth(), 1));
  const end = new Date(Date.UTC(now.getUTCFullYear(), now.getUTCMonth() + 1, 1));

  return { start: toDateString(start), end: toDateString(end) };
}

function toDateString(d: Date): string {
  return d.toISOString().slice(0, 10);
}

import "server-only";
import { createClient as createUserClient } from "@/lib/supabase/server";
import { createAdminClient } from "@/lib/supabase/admin";
import { getProvider, AIProviderError, type AIProviderName } from "@/lib/ai-provider";
import { appSettings } from "@/config/settings";
import { resolveIdentity } from "./identity";
import { resolveTool, resolveTemplate } from "./catalog";
import { resolvePlanLimits } from "./plan";
import { checkUsage } from "@/lib/limits/checkUsage";
import { resolveCompanyContext } from "./company-context";
import { buildSystemPrompt, buildUserPrompt } from "./prompt";
import { saveGeneration, incrementUsage } from "./save";
import { currentMonthPeriod } from "./period";
import { GenerationError } from "./errors";
import type { GenerateRequestBody } from "./validate";

export interface GenerateResult {
  id: string | null;
  saved: boolean;
  toolSlug: string;
  templateSlug: string | null;
  output: string;
  provider: string;
  model: string;
  usage: { inputTokens: number; outputTokens: number };
  remaining: number | "unlimited";
  /** Echoed back so a first-time guest (no token existed client-side yet
   *  is impossible today — Stage 2 always creates one before this route
   *  can be called — but this keeps the response self-describing if that
   *  ever changes). */
  guestSessionToken?: string;
}

/**
 * The Core Generate Pipeline. One linear sequence, one reason to fail at
 * each step, one place (the route handler) that turns a failure into an
 * HTTP response. Every step after this stage's Stage 8-10 tools get built
 * runs unchanged — a new tool is a new `tools`/`templates` row, not a
 * branch in this function. Steps are numbered in comments to match the
 * Stage 5 requirements list one-to-one, so it's checkable at a glance.
 */
export async function runGeneration(body: GenerateRequestBody): Promise<GenerateResult> {
  const userClient = createUserClient();
  const adminClient = createAdminClient();

  // 1. Identify the caller — signed-in user, or guest session (created/
  // refreshed here if needed; see identity.ts).
  const identity = await resolveIdentity({
    userClient,
    adminClient,
    guestSessionToken: body.guestSessionToken,
  });
  if (!identity) {
    throw new GenerationError(
      "unauthorized",
      401,
      "Sign in or include a guest session token.",
    );
  }

  // 2. Tool must exist and be active. Inactive and nonexistent look
  // identical here by design (see catalog.ts) — nothing to branch on.
  const tool = await resolveTool(userClient, body.toolSlug);
  if (!tool) {
    throw new GenerationError("tool_unavailable", 404, "This tool is not available.");
  }

  // 3. Template is optional; if named, it must exist for this tool.
  const template = body.templateSlug
    ? await resolveTemplate(userClient, body.templateSlug, tool.id)
    : null;
  if (body.templateSlug && !template) {
    throw new GenerationError("template_unavailable", 404, "This template is not available.");
  }

  // 4. Resolve the caller's plan limits (free plan for every guest).
  const planLimits = await resolvePlanLimits(userClient, identity);

  // 5. Usage limits — tool-in-plan and monthly-count in one check
  // (lib/limits/checkUsage.ts owns both, per its Stage 1 contract).
  const period = currentMonthPeriod();
  const usage = await checkUsage({
    userId: identity.type === "user" ? identity.userId : undefined,
    guestSessionId: identity.type === "guest" ? identity.guestSessionId : undefined,
    toolSlug: tool.slug,
    planLimits,
    period,
    admin: adminClient,
  });
  if (!usage.allowed) {
    const message =
      usage.reason === "tool_not_in_plan"
        ? "This tool isn't included in your current plan."
        : "You've reached your generation limit for this period.";
    throw new GenerationError(
      usage.reason === "tool_not_in_plan" ? "tool_not_in_plan" : "usage_limit_reached",
      usage.reason === "tool_not_in_plan" ? 403 : 429,
      message,
    );
  }

  // 6. Company context — real profile for a user, draft for a guest.
  // Never blocks generation; a missing profile just means a more generic
  // prompt (see prompt.ts).
  const { companyProfileId, context } = await resolveCompanyContext({
    userClient,
    identity,
    requestedCompanyProfileId: body.companyProfileId,
  });

  // 7. Build the single prompt every tool shares the assembly logic for.
  const systemPrompt = buildSystemPrompt(context, tool);
  const userPrompt = buildUserPrompt({ tool, template, inputParams: body.inputParams });

  // 8. Call the AI Provider Gateway — never a vendor SDK directly. The
  // only import of `@/lib/ai-provider` in this whole pipeline is this
  // one, right here.
  const { providerName, model } = selectProviderAndModel(planLimits);
  let aiResult;
  try {
    aiResult = await getProvider(providerName).generate({
      systemPrompt,
      userPrompt,
      model,
      maxTokens: appSettings.maxOutputTokens,
      temperature: 0.7,
    });
  } catch (error) {
    // 9. AIProviderError carries a `kind`/`retryable` the route maps to a
    // safe HTTP response (see route.ts) — nothing provider-specific
    // leaks past this catch. Anything that *isn't* an AIProviderError
    // (a bug in the gateway itself) is wrapped so the route only ever
    // has one error shape to branch on from this step onward.
    if (error instanceof AIProviderError) throw error;
    throw new GenerationError(
      "generation_failed",
      500,
      "Something went wrong generating your content.",
    );
  }

  // 10. Persist. Never throws — a storage hiccup doesn't discard an
  // already-generated (already-paid-for) result; see save.ts.
  const outcome = await saveGeneration({
    userClient,
    adminClient,
    identity,
    tool,
    template,
    companyProfileId,
    inputParams: body.inputParams,
    result: aiResult,
  });

  // 11. Usage counters — user-only; guest usage is derived on read.
  await incrementUsage(adminClient, identity, period);

  // 12. Unified response shape regardless of guest vs. authenticated.
  return {
    id: outcome.id,
    saved: outcome.saved,
    toolSlug: tool.slug,
    templateSlug: template?.slug ?? null,
    output: aiResult.text,
    provider: aiResult.provider,
    model: aiResult.model,
    usage: aiResult.usage,
    remaining: usage.remaining,
    guestSessionToken: identity.type === "guest" ? body.guestSessionToken : undefined,
  };
}

/**
 * Exactly one provider is actually implemented today (Stage 4 — Claude;
 * the other four are typed stubs). This still resolves the choice through
 * the plan's `allowedAiModels` rather than hardcoding "claude" outright,
 * so turning on a second provider later (post-MVP, per the architecture
 * doc's own roadmap) is extending this list and the map below — not
 * touching the pipeline that calls it.
 */
const IMPLEMENTED_PROVIDERS: AIProviderName[] = ["claude"];

const MODEL_BY_PROVIDER: Partial<Record<AIProviderName, string>> = {
  claude: appSettings.defaultAIModel,
};

function selectProviderAndModel(planLimits: {
  allowedAiModels: "all" | AIProviderName[];
}): { providerName: AIProviderName; model: string } {
  const allowed =
    planLimits.allowedAiModels === "all" ? IMPLEMENTED_PROVIDERS : planLimits.allowedAiModels;

  const providerName = IMPLEMENTED_PROVIDERS.find((p) => allowed.includes(p));
  const model = providerName ? MODEL_BY_PROVIDER[providerName] : undefined;

  if (!providerName || !model) {
    throw new GenerationError(
      "no_provider_available",
      500,
      "No AI provider is currently available for your plan.",
    );
  }

  return { providerName, model };
}

import "server-only";
import type { SupabaseClient } from "@supabase/supabase-js";
import type { Database } from "@/lib/supabase/database.types";
import type { AIProviderName } from "@/lib/ai-provider";

/**
 * Resolved, ready-to-use view of a plan's limits — the app-facing shape
 * `checkUsage` and provider selection consume, decoupled from the raw
 * `plan_limits` row shape (jsonb `"all" | string[]` columns normalized
 * here once, instead of every caller re-checking `=== "all"`).
 */
export interface PlanLimits {
  planSlug: "free" | "pro" | "enterprise";
  maxGenerationsPerMonth: number | null; // null = unlimited
  maxSavedResults: number | null;
  allowedToolSlugs: "all" | string[];
  allowedAiModels: "all" | AIProviderName[];
}

const FREE_PLAN_SLUG = "free";

/**
 * Both branches read through the request-scoped client (`plans`/
 * `plan_limits` are public-read reference tables per migration 0002 — no
 * need for the service-role client here), which is what keeps this safe to
 * call before any auth/guest-session check has happened.
 */
export async function resolvePlanLimits(
  supabase: SupabaseClient<Database>,
  identity: { type: "user"; userId: string } | { type: "guest" },
): Promise<PlanLimits> {
  const planSlug =
    identity.type === "user"
      ? await resolveUserPlanSlug(supabase, identity.userId)
      : FREE_PLAN_SLUG;

  const { data, error } = await supabase
    .from("plans")
    .select("slug, plan_limits(max_generations_per_month, max_saved_results, allowed_tool_ids, allowed_ai_models)")
    .eq("slug", planSlug)
    .single();

  if (error || !data || !data.plan_limits) {
    // Seed data missing or a plan with no matching plan_limits row — fail
    // closed (zero generations allowed) rather than open (unlimited),
    // since the alternative failure mode is silently free AI usage.
    return {
      planSlug: FREE_PLAN_SLUG,
      maxGenerationsPerMonth: 0,
      maxSavedResults: 0,
      allowedToolSlugs: [],
      allowedAiModels: [],
    };
  }

  // Cast rather than lean on inferred typing: database.types.ts is
  // hand-written (see Stage 3 audit) and doesn't carry the `Relationships`
  // metadata supabase-js uses to type nested embeds like `plan_limits(...)`
  // precisely — the shape below is correct per the migration, but wasn't
  // checked against a real generated type. Re-verify once
  // `supabase gen types` replaces the hand-written file.
  const rawLimits = data.plan_limits as unknown as
    | {
        max_generations_per_month: number | null;
        max_saved_results: number | null;
        allowed_tool_ids: unknown;
        allowed_ai_models: unknown;
      }
    | Array<{
        max_generations_per_month: number | null;
        max_saved_results: number | null;
        allowed_tool_ids: unknown;
        allowed_ai_models: unknown;
      }>;
  const limits = Array.isArray(rawLimits) ? rawLimits[0] : rawLimits;

  return {
    planSlug: data.slug as "free" | "pro" | "enterprise",
    maxGenerationsPerMonth: limits.max_generations_per_month,
    maxSavedResults: limits.max_saved_results,
    allowedToolSlugs: normalizeSlugList(limits.allowed_tool_ids),
    allowedAiModels: normalizeSlugList(limits.allowed_ai_models) as "all" | AIProviderName[],
  };
}

async function resolveUserPlanSlug(
  supabase: SupabaseClient<Database>,
  userId: string,
): Promise<"free" | "pro" | "enterprise"> {
  const { data } = await supabase
    .from("users")
    .select("plans(slug)")
    .eq("id", userId)
    .single();

  // Same caveat as above: cast, not inferred — see comment in resolvePlanLimits.
  const rawPlan = data?.plans as unknown as { slug: string } | { slug: string }[] | null;
  const plan = rawPlan ? (Array.isArray(rawPlan) ? rawPlan[0] : rawPlan) : null;
  return (plan?.slug as "free" | "pro" | "enterprise" | undefined) ?? FREE_PLAN_SLUG;
}

function normalizeSlugList(value: unknown): "all" | string[] {
  if (value === "all") return "all";
  if (Array.isArray(value)) return value.filter((v): v is string => typeof v === "string");
  return [];
}

import type { CompanyContext } from "./company-context";
import type { ResolvedTemplate, ResolvedTool } from "./catalog";

/**
 * Turns company context + template + input params into the two strings
 * the AI Provider Gateway actually wants. This is the one place that
 * combines those three things — every tool (Stage 8 onward) goes through
 * this same function instead of building its own prompt assembly, which
 * is what makes "add a tool = a config row" (project architecture doc §14)
 * true rather than aspirational.
 *
 * No per-tool special-casing lives here on purpose: the moment this file
 * needs an `if (tool.slug === "...")`, that's a sign the tool needs a
 * proper prompt_template row instead.
 */

export function buildSystemPrompt(context: CompanyContext | null, tool: ResolvedTool): string {
  const lines = [
    `You are the "${tool.name}" tool inside AI Marketing Workspace, an AI marketing platform for small businesses. Write copy that is ready to use with minimal editing.`,
  ];

  if (context && hasAnyField(context)) {
    lines.push("", "Company context to tailor your output to:");
    if (context.name) lines.push(`- Company name: ${context.name}`);
    if (context.niche) lines.push(`- Niche/industry: ${context.niche}`);
    if (context.targetAudience) lines.push(`- Target audience: ${context.targetAudience}`);
    if (context.toneOfVoice) lines.push(`- Tone of voice: ${context.toneOfVoice}`);
    if (context.usp) lines.push(`- Unique selling point: ${context.usp}`);
    if (context.websiteUrl) lines.push(`- Website: ${context.websiteUrl}`);
  } else {
    lines.push(
      "",
      "No company profile is available yet — write generically useful marketing copy and avoid inventing specific company facts, names, or claims.",
    );
  }

  return lines.join("\n");
}

export function buildUserPrompt(params: {
  tool: ResolvedTool;
  template: ResolvedTemplate | null;
  inputParams: Record<string, unknown>;
}): string {
  if (params.template) {
    return fillTemplate(params.template.promptTemplate, params.inputParams);
  }

  // No template selected (or none exist yet for this tool — the
  // `templates` table is seeded starting Stage 10). Falls back to a
  // structured-but-generic prompt from the raw params rather than
  // failing the request, so the pipeline is exercisable end-to-end before
  // any real template content exists.
  return [
    `Task: ${params.tool.name}`,
    "",
    "Parameters:",
    JSON.stringify(params.inputParams, null, 2),
  ].join("\n");
}

function hasAnyField(context: CompanyContext): boolean {
  return Object.values(context).some((v) => typeof v === "string" && v.trim() !== "");
}

/** Replaces {{field}} tokens; unknown/missing fields resolve to "". */
function fillTemplate(template: string, values: Record<string, unknown>): string {
  return template.replace(/\{\{\s*(\w+)\s*\}\}/g, (_match, key: string) => {
    const value = values[key];
    return value === undefined || value === null ? "" : String(value);
  });
}

import "server-only";
import type { SupabaseClient } from "@supabase/supabase-js";
import type { Database } from "@/lib/supabase/database.types";
import type { Identity } from "./identity";
import type { UsagePeriod } from "./period";
import type { AIGenerateResult } from "@/lib/ai-provider";
import type { ResolvedTool, ResolvedTemplate } from "./catalog";

export interface SaveGenerationParams {
  /** Request-scoped, RLS-enforced client — used for signed-in writes. */
  userClient: SupabaseClient<Database>;
  /** Service-role client — used only for guest writes (see lib/supabase/admin.ts). */
  adminClient: SupabaseClient<Database>;
  identity: Identity;
  tool: ResolvedTool;
  template: ResolvedTemplate | null;
  companyProfileId: string | null;
  inputParams: Record<string, unknown>;
  result: AIGenerateResult;
}

export interface SaveGenerationOutcome {
  id: string | null;
  saved: boolean;
}

/**
 * Signed-in writes go through `userClient` (the caller's own session,
 * RLS-scoped to `auth.uid() = user_id` per migration 0008) rather than the
 * admin client — see the Stage 3 audit's rationale for why `generations`
 * carries an authenticated INSERT policy at all: it's what lets this stay
 * defense-in-depth even from trusted server code. Guest writes have no
 * `auth.uid()` to scope to, so they're the one case that has to use the
 * admin client.
 *
 * Never throws: a failed save doesn't mean the AI call failed too — the
 * text the person is looking at already exists. Swallowing the DB error
 * here and reporting `saved: false` instead means the route can still
 * hand back the generated output (so they can copy it) rather than
 * discarding a paid-for AI response because of an unrelated storage
 * hiccup.
 */
export async function saveGeneration(
  params: SaveGenerationParams,
): Promise<SaveGenerationOutcome> {
  const client = params.identity.type === "user" ? params.userClient : params.adminClient;

  const row = {
    user_id: params.identity.type === "user" ? params.identity.userId : null,
    guest_session_id: params.identity.type === "guest" ? params.identity.guestSessionId : null,
    company_profile_id: params.companyProfileId,
    tool_id: params.tool.id,
    template_id: params.template?.id ?? null,
    ai_provider: params.result.provider,
    ai_model: params.result.model,
    input_params: params.inputParams,
    output: params.result.text,
  };

  const { data, error } = await client.from("generations").insert(row).select("id").single();

  if (error || !data) {
    console.error("[generations] save failed:", error?.message);
    return { id: null, saved: false };
  }

  return { id: data.id, saved: true };
}

/**
 * User-only: guest usage is derived on read (countGuestGenerations in
 * checkUsage.ts), not accumulated in a counter, so there's nothing to
 * increment for a guest identity.
 *
 * Uses the `increment_usage_counter` Postgres function (migration 0011)
 * rather than a select-then-update from this client — two round trips
 * with no transaction between them would race under real concurrent
 * requests from the same user (two tabs, a retry). The function performs
 * an atomic upsert; this call either creates the period's row at count 1
 * or increments it, with no window for a lost update.
 *
 * Counted even if `saveGeneration` above reported `saved: false`: the AI
 * provider call already happened and already cost real money regardless
 * of whether the DB write succeeded, so not counting it would let a
 * transient storage failure become a free, uncounted generation.
 */
export async function incrementUsage(
  adminClient: SupabaseClient<Database>,
  identity: Identity,
  period: UsagePeriod,
): Promise<void> {
  if (identity.type !== "user") return;

  const { error } = await adminClient.rpc("increment_usage_counter", {
    p_user_id: identity.userId,
    p_period_start: period.start,
    p_period_end: period.end,
  });

  if (error) {
    // Not thrown: the generation already succeeded and (if saveGeneration
    // succeeded) is already saved. Losing an increment means this one
    // period undercounts by one — worth logging, not worth failing an
    // otherwise-successful request over.
    console.error("[usage_counters] increment failed:", error.message);
  }
}

import "server-only";
import { z } from "zod";
import { GenerationError } from "./errors";

/**
 * First request body in the project complex enough to earn a real schema
 * library rather than hand-rolled `if` checks (config JSON files and the
 * merge endpoint's one-field body didn't need this) — zod gives runtime
 * validation and the TypeScript type from the same declaration, so the
 * two can't drift apart the way a hand-written validator + a hand-written
 * interface could.
 */
const MAX_INPUT_PARAMS_JSON_LENGTH = 20_000;

export const GenerateRequestSchema = z
  .object({
    toolSlug: z.string().trim().min(1).max(100),
    templateSlug: z.string().trim().min(1).max(100).optional(),
    companyProfileId: z.string().uuid().optional(),
    guestSessionToken: z.string().trim().min(10).max(200).optional(),
    inputParams: z.record(z.string(), z.unknown()).default({}),
  })
  .refine((body) => JSON.stringify(body.inputParams).length <= MAX_INPUT_PARAMS_JSON_LENGTH, {
    message: `inputParams is too large (max ${MAX_INPUT_PARAMS_JSON_LENGTH} JSON characters).`,
    path: ["inputParams"],
  });

export type GenerateRequestBody = z.infer<typeof GenerateRequestSchema>;

export async function parseGenerateRequest(request: Request): Promise<GenerateRequestBody> {
  let json: unknown;
  try {
    json = await request.json();
  } catch {
    throw new GenerationError("invalid_json", 400, "Request body must be valid JSON.");
  }

  const result = GenerateRequestSchema.safeParse(json);
  if (!result.success) {
    // .issues is safe to summarize back to the client — these are our own
    // field names and constraints, not internal error detail (contrast
    // with AI provider / DB errors, which never get echoed as-is).
    const firstIssue = result.error.issues[0];
    throw new GenerationError(
      "validation_error",
      400,
      firstIssue ? `${firstIssue.path.join(".")}: ${firstIssue.message}` : "Invalid request body.",
    );
  }

  return result.data;
}

"use client";

import {
  createContext,
  useContext,
  useEffect,
  useState,
  useCallback,
  type ReactNode,
} from "react";
import {
  ensureGuestSession,
  updateGuestProfileDraft,
  clearGuestSession,
} from "./storage";
import type { GuestCompanyProfileDraft, GuestSession } from "./types";

interface GuestSessionContextValue {
  /** null until the effect on first client render has run (SSR-safe). */
  session: GuestSession | null;
  setProfileDraft: (draft: GuestCompanyProfileDraft) => void;
  clear: () => void;
}

const GuestSessionContext = createContext<GuestSessionContextValue | null>(
  null,
);

export function GuestSessionProvider({ children }: { children: ReactNode }) {
  // Starts null so server-rendered and first-client-render markup match
  // (localStorage doesn't exist on the server) — populated in the effect.
  const [session, setSession] = useState<GuestSession | null>(null);

  useEffect(() => {
    setSession(ensureGuestSession());
  }, []);

  const setProfileDraft = useCallback((draft: GuestCompanyProfileDraft) => {
    setSession(updateGuestProfileDraft(draft));
  }, []);

  const clear = useCallback(() => {
    clearGuestSession();
    setSession(null);
  }, []);

  return (
    <GuestSessionContext.Provider value={{ session, setProfileDraft, clear }}>
      {children}
    </GuestSessionContext.Provider>
  );
}

export function useGuestSession(): GuestSessionContextValue {
  const ctx = useContext(GuestSessionContext);
  if (!ctx) {
    throw new Error(
      "useGuestSession must be used within <GuestSessionProvider>",
    );
  }
  return ctx;
}

import { appSettings } from "@/config/settings";
import type { GuestCompanyProfileDraft, GuestSession } from "./types";

/**
 * Low-level localStorage read/write for the guest session. Kept dependency-
 * free and framework-free on purpose (no React here) so it can be called
 * from the auth-sync listener, the context provider, or a future non-React
 * caller without pulling in React.
 *
 * `lib/guest-session/context.tsx` is the React-facing API most components
 * should use instead of calling this module directly.
 */

const STORAGE_KEY = "amw_guest_session";

function isBrowser(): boolean {
  return typeof window !== "undefined";
}

function generateSessionToken(): string {
  // crypto.randomUUID is available in all modern browsers and in the
  // Edge/Node runtimes Next.js uses — no uuid dependency needed.
  return crypto.randomUUID();
}

export function readGuestSession(): GuestSession | null {
  if (!isBrowser()) return null;
  const raw = window.localStorage.getItem(STORAGE_KEY);
  if (!raw) return null;

  try {
    const parsed = JSON.parse(raw) as GuestSession;
    if (new Date(parsed.expiresAt).getTime() < Date.now()) {
      window.localStorage.removeItem(STORAGE_KEY);
      return null;
    }
    return parsed;
  } catch {
    // Corrupt value (e.g. edited by hand, or a shape from a future version) —
    // fail safe by discarding rather than throwing.
    window.localStorage.removeItem(STORAGE_KEY);
    return null;
  }
}

export function createGuestSession(): GuestSession {
  const now = new Date();
  const expires = new Date(
    now.getTime() + appSettings.guestSessionTtlDays * 24 * 60 * 60 * 1000,
  );

  const session: GuestSession = {
    sessionToken: generateSessionToken(),
    companyProfileDraft: null,
    createdAt: now.toISOString(),
    expiresAt: expires.toISOString(),
  };

  if (isBrowser()) {
    window.localStorage.setItem(STORAGE_KEY, JSON.stringify(session));
  }
  return session;
}

export function ensureGuestSession(): GuestSession {
  return readGuestSession() ?? createGuestSession();
}

export function updateGuestProfileDraft(
  draft: GuestCompanyProfileDraft,
): GuestSession {
  const current = ensureGuestSession();
  const updated: GuestSession = { ...current, companyProfileDraft: draft };
  if (isBrowser()) {
    window.localStorage.setItem(STORAGE_KEY, JSON.stringify(updated));
  }
  return updated;
}

export function clearGuestSession(): void {
  if (!isBrowser()) return;
  window.localStorage.removeItem(STORAGE_KEY);
}

/**
 * Guest session contract.
 *
 * Shape is deliberately identical to the future `guest_sessions` table
 * (project architecture doc, section 4):
 *   guest_sessions (id, session_token, company_profile_draft jsonb,
 *                    created_at, expires_at)
 *
 * `id` is server-generated once the table exists (Stage 3) and is not part
 * of this client-side contract — `session_token` is the client-generated,
 * client-held identifier that both the pre-DB (Stage 2) and post-DB
 * (Stage 3+) worlds key off of, so nothing here needs to change shape when
 * the table is created.
 */
export interface GuestCompanyProfileDraft {
  name?: string;
  niche?: string;
  toneOfVoice?: string;
  targetAudience?: string;
  usp?: string;
  websiteUrl?: string;
}

export interface GuestSession {
  sessionToken: string;
  companyProfileDraft: GuestCompanyProfileDraft | null;
  createdAt: string; // ISO 8601
  expiresAt: string; // ISO 8601
}

import "server-only";
import type { SupabaseClient } from "@supabase/supabase-js";
import type { Database } from "@/lib/supabase/database.types";
import type { PlanLimits } from "@/lib/generation/plan";
import type { UsagePeriod } from "@/lib/generation/period";

/**
 * Original Stage 1 contract (unchanged): callers get `allowed`, `remaining`,
 * and — on rejection — a `reason` telling them which check failed. Stage 5
 * fills in the implementation; nothing about the shape changed, so nothing
 * that types against this interface elsewhere needs to change either.
 */
export interface UsageCheckResult {
  allowed: boolean;
  remaining: number | "unlimited";
  reason?: "monthly_limit_reached" | "tool_not_in_plan";
}

export async function checkUsage(params: {
  userId?: string;
  guestSessionId?: string;
  toolSlug: string;
  planLimits: PlanLimits;
  period: UsagePeriod;
  /** Service-role client — required because usage_counters has no
   *  client-facing read policy for this cross-period lookup pattern, and
   *  a guest's own generation count is only readable this way too (see
   *  lib/supabase/admin.ts for the full rationale). */
  admin: SupabaseClient<Database>;
}): Promise<UsageCheckResult> {
  const { planLimits } = params;

  const toolAllowed =
    planLimits.allowedToolSlugs === "all" ||
    planLimits.allowedToolSlugs.includes(params.toolSlug);

  if (!toolAllowed) {
    return { allowed: false, remaining: 0, reason: "tool_not_in_plan" };
  }

  if (planLimits.maxGenerationsPerMonth === null) {
    return { allowed: true, remaining: "unlimited" };
  }

  const currentCount = params.userId
    ? await countUserGenerationsThisPeriod(params.admin, params.userId, params.period)
    : await countGuestGenerations(params.admin, params.guestSessionId);

  const allowed = currentCount < planLimits.maxGenerationsPerMonth;

  if (!allowed) {
    return { allowed: false, remaining: 0, reason: "monthly_limit_reached" };
  }

  // "Remaining after this one" — the request currently being checked
  // hasn't been saved yet, so it isn't in `currentCount`; subtracting 1
  // here reports what the caller will have left once it goes through,
  // which is what a UI usage indicator (Stage 13) actually wants to show.
  return { allowed: true, remaining: planLimits.maxGenerationsPerMonth - currentCount - 1 };
}

async function countUserGenerationsThisPeriod(
  admin: SupabaseClient<Database>,
  userId: string,
  period: UsagePeriod,
): Promise<number> {
  const { data } = await admin
    .from("usage_counters")
    .select("generations_count")
    .eq("user_id", userId)
    .eq("period_start", period.start)
    .maybeSingle();

  return data?.generations_count ?? 0;
}

/**
 * Guests have no `usage_counters` row (that table is scoped to `user_id`,
 * migration 0007) — a monthly period wouldn't mean much for a session
 * that's TTL'd out after `guestSessionTtlDays` anyway (config/settings.ts).
 * Counting the guest's own generations directly is simpler, exact, and
 * needs no separate table just for a state that only exists for ~30 days.
 */
async function countGuestGenerations(
  admin: SupabaseClient<Database>,
  guestSessionId: string | undefined,
): Promise<number> {
  if (!guestSessionId) return 0;

  const { count } = await admin
    .from("generations")
    .select("id", { count: "exact", head: true })
    .eq("guest_session_id", guestSessionId);

  return count ?? 0;
}

import "server-only";
import { createClient as createSupabaseClient } from "@supabase/supabase-js";
import type { Database } from "./database.types";

/**
 * Service-role Supabase client — bypasses RLS entirely. Deliberately not
 * created back in Stage 1/2/3: those stages had no code that actually
 * needed it, and an unused privileged client sitting in the tree is a risk
 * with no offsetting benefit. Stage 5 is the first real caller:
 *
 * - `guest_sessions` (migration 0005) has RLS enabled with NO client
 *   policies at all — the only way to read/write it is this client.
 * - `usage_counters` (migration 0007) has no client write policy — same.
 * - `generations` rows owned by a guest (`guest_session_id` set, `user_id`
 *   null) are equally unreachable under RLS for an unauthenticated caller.
 *
 * Rules for using this file:
 * 1. Only ever import it from server-only code that already knows it's
 *    handling a privileged operation (see lib/generation/*, never a
 *    Server Component that's just reading data a normal user-scoped
 *    client could read).
 * 2. Never construct it with anything other than
 *    `SUPABASE_SERVICE_ROLE_KEY` — that variable has no `NEXT_PUBLIC_`
 *    prefix specifically so Next.js never inlines it into a client bundle.
 * 3. Prefer the request-scoped client (lib/supabase/server.ts) whenever
 *    RLS alone is sufficient — every extra caller of this file is a place
 *    a future bug could bypass row-level security by accident.
 */
export function createAdminClient() {
  const url = process.env.NEXT_PUBLIC_SUPABASE_URL;
  const serviceRoleKey = process.env.SUPABASE_SERVICE_ROLE_KEY;

  if (!url || !serviceRoleKey) {
    throw new Error(
      "Supabase admin client requires NEXT_PUBLIC_SUPABASE_URL and SUPABASE_SERVICE_ROLE_KEY.",
    );
  }

  return createSupabaseClient<Database>(url, serviceRoleKey, {
    auth: { autoRefreshToken: false, persistSession: false },
  });
}

import "server-only";
import { redirect } from "next/navigation";
import { createClient } from "./server";

/**
 * Server-side auth helpers, for use in Server Components / Server Actions /
 * Route Handlers only (the "server-only" import makes an accidental client
 * import a build error rather than a runtime surprise).
 */

export async function getUser() {
  const supabase = createClient();
  const {
    data: { user },
  } = await supabase.auth.getUser();
  return user;
}

/**
 * Use at the top of a protected Server Component/layout. Middleware already
 * redirects unauthenticated requests away from `(auth)` routes — this is
 * the defense-in-depth check for the rare paths middleware can't cover
 * (e.g. a Server Action invoked directly), so `(auth)/layout.tsx` never
 * renders protected content for a logged-out request even if middleware is
 * skipped or misconfigured.
 */
export async function requireUser() {
  const user = await getUser();
  if (!user) {
    redirect("/login");
  }
  return user;
}

import { createBrowserClient } from "@supabase/ssr";
import type { Database } from "./database.types";

/**
 * Browser-side Supabase client. Safe to use in client components.
 * Only the public URL + anon key are exposed here — never the service role key.
 */
export function createClient() {
  return createBrowserClient<Database>(
    process.env.NEXT_PUBLIC_SUPABASE_URL!,
    process.env.NEXT_PUBLIC_SUPABASE_ANON_KEY!,
  );
}

/**
 * Hand-written to match supabase/migrations/*.sql exactly, because
 * `supabase gen types typescript` requires a live, linked project and
 * network access — neither available in this environment. Once the
 * project exists (after running Stage 3's migrations), regenerate this
 * file for real:
 *
 *   npx supabase gen types typescript --project-id <ref> > lib/supabase/database.types.ts
 *
 * and diff it against this version — they should match. Until then, this
 * is what gives `createClient<Database>()` real autocomplete and type
 * checking instead of `any`.
 */

export interface Database {
  public: {
    Tables: {
      users: {
        Row: {
          id: string;
          email: string;
          plan_id: string | null;
          created_at: string;
          updated_at: string;
        };
        Insert: {
          id: string;
          email: string;
          plan_id?: string | null;
          created_at?: string;
          updated_at?: string;
        };
        Update: Partial<Database["public"]["Tables"]["users"]["Insert"]>;
      };
      company_profiles: {
        Row: {
          id: string;
          user_id: string;
          name: string;
          niche: string | null;
          tone_of_voice: string | null;
          target_audience: string | null;
          usp: string | null;
          website_url: string | null;
          logo_url: string | null;
          created_at: string;
          updated_at: string;
        };
        Insert: {
          id?: string;
          user_id: string;
          name: string;
          niche?: string | null;
          tone_of_voice?: string | null;
          target_audience?: string | null;
          usp?: string | null;
          website_url?: string | null;
          logo_url?: string | null;
          created_at?: string;
          updated_at?: string;
        };
        Update: Partial<Database["public"]["Tables"]["company_profiles"]["Insert"]>;
      };
      guest_sessions: {
        Row: {
          id: string;
          session_token: string;
          company_profile_draft: Record<string, unknown> | null;
          created_at: string;
          expires_at: string;
          updated_at: string;
        };
        Insert: {
          id?: string;
          session_token: string;
          company_profile_draft?: Record<string, unknown> | null;
          created_at?: string;
          expires_at: string;
          updated_at?: string;
        };
        Update: Partial<Database["public"]["Tables"]["guest_sessions"]["Insert"]>;
      };
      tools: {
        Row: {
          id: string;
          slug: string;
          name: string;
          description: string | null;
          icon: string | null;
          category: string | null;
          config_schema: Record<string, unknown>;
          is_active: boolean;
          created_at: string;
          updated_at: string;
        };
        Insert: {
          id?: string;
          slug: string;
          name: string;
          description?: string | null;
          icon?: string | null;
          category?: string | null;
          config_schema?: Record<string, unknown>;
          is_active?: boolean;
          created_at?: string;
          updated_at?: string;
        };
        Update: Partial<Database["public"]["Tables"]["tools"]["Insert"]>;
      };
      templates: {
        Row: {
          id: string;
          tool_id: string;
          slug: string;
          name: string;
          category: string;
          prompt_template: string;
          required_fields: unknown[];
          is_premium: boolean;
          created_at: string;
          updated_at: string;
        };
        Insert: {
          id?: string;
          tool_id: string;
          slug: string;
          name: string;
          category: string;
          prompt_template?: string;
          required_fields?: unknown[];
          is_premium?: boolean;
          created_at?: string;
          updated_at?: string;
        };
        Update: Partial<Database["public"]["Tables"]["templates"]["Insert"]>;
      };
      plans: {
        Row: {
          id: string;
          slug: "free" | "pro" | "enterprise";
          name: string;
          price_month: number | null;
          is_active: boolean;
          created_at: string;
          updated_at: string;
        };
