import { createServerClient } from "@supabase/ssr";
import { NextResponse, type NextRequest } from "next/server";
import type { Database } from "./database.types";

/**
 * Refreshes the Supabase auth cookie on every request that passes through
 * the root middleware, and returns both the (possibly redirected) response
 * and the resolved user — so middleware.ts can make a routing decision
 * without a second round-trip.
 *
 * Follows the official @supabase/ssr Next.js middleware pattern: cookies
 * must be read/written on both the request and the response objects.
 * Uses `getAll`/`setAll`, not the older `get`/`set`/`remove` this file
 * used against @supabase/ssr ^0.4.0 (Stage 2) — same migration and same
 * reasoning as lib/supabase/server.ts (see its comment for the full
 * explanation; verified via web search during Phase 1's build check).
 * `updateSession`'s own signature and `{response, user}` return shape
 * are unchanged, so root middleware.ts needs no changes either.
 */
export async function updateSession(request: NextRequest) {
  let response = NextResponse.next({ request: { headers: request.headers } });

  const supabase = createServerClient<Database>(
    process.env.NEXT_PUBLIC_SUPABASE_URL!,
    process.env.NEXT_PUBLIC_SUPABASE_ANON_KEY!,
    {
      cookies: {
        getAll() {
          return request.cookies.getAll();
        },
        setAll(cookiesToSet) {
          cookiesToSet.forEach(({ name, value }) => request.cookies.set(name, value));
          response = NextResponse.next({ request: { headers: request.headers } });
          cookiesToSet.forEach(({ name, value, options }) =>
            response.cookies.set(name, value, options),
          );
        },
      },
    },
  );

  // Must call getUser() (not getSession()) here — it revalidates the token
  // against Supabase rather than trusting the cookie as-is, which is what
  // makes this safe to use for routing decisions.
  const {
    data: { user },
  } = await supabase.auth.getUser();

  return { response, user };
}

import { createServerClient } from "@supabase/ssr";
import { cookies } from "next/headers";
import type { Database } from "./database.types";

/**
 * Server-side Supabase client (Server Components, Route Handlers, Server Actions).
 * Reads/writes the auth cookie via Next's cookies() API.
 *
 * Uses `getAll`/`setAll` — the only cookie methods @supabase/ssr 0.12.x
 * accepts; the older `get`/`set`/`remove` shape this file used against
 * @supabase/ssr ^0.4.0 (Stage 2) is rejected by the client library at
 * runtime in current versions ("You MUST use ONLY getAll and setAll",
 * per Supabase's own current Next.js integration guide). Verified via
 * web search during Phase 1 (build) — not available when this file was
 * first written, since this project's own environment has never had
 * network access to check.
 *
 * `cookies()` itself stays un-awaited: Next.js 14.2.5 (this project's
 * pinned version) still returns the cookie store synchronously — the
 * `await cookies()` pattern shown in Supabase's current docs is for
 * Next.js 15+, where `cookies()` became async. This function's own
 * signature is unchanged (still synchronous, still returns
 * `SupabaseClient<Database>` directly, not a Promise) specifically so
 * none of its ~13 call sites across the project need to change.
 *
 * No RLS-bypassing service-role client is exposed from here on purpose —
 * that belongs in a separate, explicitly-named `admin.ts` once it's actually
 * needed (Stage 3+), so it's never reached for by accident.
 */
export function createClient() {
  const cookieStore = cookies();

  return createServerClient<Database>(
    process.env.NEXT_PUBLIC_SUPABASE_URL!,
    process.env.NEXT_PUBLIC_SUPABASE_ANON_KEY!,
    {
      cookies: {
        getAll() {
          return cookieStore.getAll();
        },
        setAll(cookiesToSet) {
          try {
            cookiesToSet.forEach(({ name, value, options }) =>
              cookieStore.set(name, value, options),
            );
          } catch {
            // `setAll` was called from a Server Component, which can't
            // set cookies directly — safe to ignore here because
            // middleware.ts's updateSession() refreshes the session on
            // every request anyway (same reasoning Supabase's own
            // reference implementation documents for this exact catch).
          }
        },
      },
    },
  );
}

import "server-only";
import type { SupabaseClient } from "@supabase/supabase-js";
import type { Database } from "@/lib/supabase/database.types";
import type { TemplateListItem } from "./types";

/**
 * Lists every template whose owning tool is active, for the Templates
 * Library. Not a duplicate of lib/generation/catalog.ts's
 * resolveTemplate()/resolveDefaultTemplate(): those look up exactly one
 * template — by slug, or by "first for this tool" — for the generation
 * pipeline and the tool page; this lists *all* of them, joined with their
 * tool's slug/name, for browsing. Same relationship to
 * lib/generation/catalog.ts as lib/tools/catalog.ts already has to it
 * (Stage 7) — a different query shape for a different consumer, not a
 * second version of the same one.
 *
 * The `tools!inner(...)` join + `.eq("tools.is_active", true)` matters:
 * `templates`' own RLS policy (migration 0006) is `using (true)` — it has
 * no idea whether a template's owning tool is active, only `tools`' RLS
 * does. Every template in this project happens to belong to an active
 * tool today (Stage 8/9), so this was latent, not visible, until now —
 * resolveTemplate()/resolveDefaultTemplate() are only ever called after
 * resolveTool() has already confirmed the tool is active, so they never
 * needed this check themselves. This function is the first one that
 * lists templates *without* going through resolveTool() first, so it's
 * the first place a template belonging to a since-deactivated tool could
 * actually surface — a real card linking to a "not available" page. The
 * filter is applied here, in the query, not by changing the RLS policy
 * (which would be a schema change touching a file this stage has no
 * objective need to modify).
 */
export async function listTemplates(
  supabase: SupabaseClient<Database>,
): Promise<TemplateListItem[]> {
  const { data, error } = await supabase
    .from("templates")
    .select("slug, name, category, tools!inner(slug, name, is_active)")
    .eq("tools.is_active", true)
    .order("name", { ascending: true });

  if (error) {
    throw new TemplateCatalogError("Failed to load templates.", error);
  }

  return (data ?? []).map((row) => {
    // Cast, not inferred — same caveat as lib/generation/plan.ts (Stage 5):
    // database.types.ts is hand-written and doesn't carry the
    // `Relationships` metadata supabase-js uses to type a `!inner` embed
    // precisely.
    const tool = row.tools as unknown as { slug: string; name: string; is_active: boolean };
    return {
      slug: row.slug,
      name: row.name,
      category: row.category,
      toolSlug: tool.slug,
      toolName: tool.name,
    };
  });
}

export class TemplateCatalogError extends Error {
  constructor(
    message: string,
    public readonly cause?: unknown,
  ) {
    super(message);
    this.name = "TemplateCatalogError";
  }
}

import type { TemplateListItem } from "./types";

/**
 * Deliberately NOT sharing an abstraction with lib/tools/query.ts
 * (Stage 7), even though the two functions are structurally similar
 * (filter by search text, filter by category, sort by name). Considered
 * and rejected: extracting a shared generic utility would mean either
 * refactoring lib/tools/query.ts to use it — touching already-shipped,
 * already-audited Stage 7 code with no objective need this stage — or
 * building the shared utility only for this file to use, leaving two
 * different patterns for conceptually similar logic, which is worse than
 * two small independent ones. The search fields also genuinely differ
 * (name+description for tools, name+category for templates — templates
 * has no description column) and the two are free to diverge further
 * later (templates might filter by is_premium; tools might not) without
 * dragging a shared abstraction along. Same reasoning Stage 7 used to
 * justify lib/tools/ existing alongside lib/generation/catalog.ts in the
 * first place: reuse the *pattern*, not force-share the *code*.
 */
export type TemplateSortOption = "name";

export interface TemplateQueryParams {
  search?: string;
  category?: string | null;
  sortBy?: TemplateSortOption;
}

export function queryTemplates(
  templates: TemplateListItem[],
  params: TemplateQueryParams,
): TemplateListItem[] {
  let result = templates;

  const search = params.search?.trim().toLowerCase();
  if (search) {
    result = result.filter(
      (template) =>
        template.name.toLowerCase().includes(search) ||
        template.category.toLowerCase().includes(search),
    );
  }

  if (params.category) {
    result = result.filter((template) => template.category === params.category);
  }

  return sortTemplates(result, params.sortBy ?? "name");
}

function sortTemplates(
  templates: TemplateListItem[],
  sortBy: TemplateSortOption,
): TemplateListItem[] {
  const sorted = [...templates];

  switch (sortBy) {
    case "name":
      sorted.sort((a, b) => a.name.localeCompare(b.name));
      break;
  }

  return sorted;
}

/** `category` is NOT NULL on `templates` (unlike `tools.category`, which
 *  is nullable) — no filtering-out-empty-values step needed here that
 *  lib/tools/query.ts's deriveCategories has to do. */
export function deriveCategories(templates: TemplateListItem[]): string[] {
  const categories = new Set<string>();
  for (const template of templates) {
    categories.add(template.category);
  }
  return Array.from(categories).sort((a, b) => a.localeCompare(b));
}

/**
 * Shape the Templates Library renders against. Mirrors the reasoning of
 * lib/tools/types.ts's ToolListItem exactly (Stage 7): only the fields a
 * card and a link actually need, nothing carried "in case it's useful."
 *
 * `toolSlug`/`toolName` (not `toolId`) because the only thing a template
 * card does with its owning tool is link to `/tools/{slug}` and show the
 * tool's name — an id would be dead weight here, same reasoning that kept
 * `id` off ToolListItem.
 *
 * No `description`: `templates` has no such column (unlike `tools`,
 * which gained one in Stage 7) and Stage 10's brief never asked for one
 * for templates specifically — name + category + source tool is enough
 * for a card, so adding a column for it would be exactly the kind of
 * unrequested, ungrounded schema change this stage is told to avoid.
 */
export interface TemplateListItem {
  slug: string;
  name: string;
  category: string;
  toolSlug: string;
  toolName: string;
}

import type { ToolConfigSchema } from "./schema";

/** Seeds form state from each field's `defaultValue` (or `false` for an
 *  unchecked checkbox, so it's always a controlled boolean from the start
 *  rather than `undefined`). */
export function buildInitialValues(schema: ToolConfigSchema): Record<string, unknown> {
  const values: Record<string, unknown> = {};

  for (const field of schema.fields) {
    if (field.defaultValue !== undefined) {
      values[field.name] = field.defaultValue;
    } else if (field.type === "checkbox") {
      values[field.name] = false;
    }
  }

  return values;
}

import { z } from "zod";

/**
 * The field-config format every tool's `tools.config_schema` (jsonb) is
 * expected to follow, and the single source of truth ToolRunner renders
 * against. This is Stage 6's actual deliverable as much as the React
 * components are: Postgres doesn't validate the *shape* of a jsonb
 * column, only that it's valid JSON, so this schema is what turns
 * "config, not code" (project architecture doc §14) from an aspiration
 * into something a malformed row can't silently break.
 *
 * Adding a new field type later means: one new branch here, one new
 * component in components/tools/fields/, one new registry line in
 * components/tools/fields/index.ts. Nothing else in ToolRunner,
 * FieldRenderer, or any existing field component changes.
 */

const baseField = {
  name: z.string().min(1).max(100),
  label: z.string().min(1).max(200),
  helpText: z.string().max(500).optional(),
  placeholder: z.string().max(200).optional(),
  required: z.boolean().optional(),
};

export const TextFieldSchema = z.object({
  ...baseField,
  type: z.literal("text"),
  defaultValue: z.string().optional(),
  minLength: z.number().int().nonnegative().optional(),
  maxLength: z.number().int().positive().optional(),
  pattern: z.string().optional(),
});

export const TextareaFieldSchema = z.object({
  ...baseField,
  type: z.literal("textarea"),
  defaultValue: z.string().optional(),
  maxLength: z.number().int().positive().optional(),
  rows: z.number().int().positive().max(20).optional(),
});

export const NumberFieldSchema = z.object({
  ...baseField,
  type: z.literal("number"),
  defaultValue: z.number().optional(),
  min: z.number().optional(),
  max: z.number().optional(),
  step: z.number().positive().optional(),
});

export const EmailFieldSchema = z.object({
  ...baseField,
  type: z.literal("email"),
  defaultValue: z.string().optional(),
});

const optionSchema = z.object({
  label: z.string().min(1).max(200),
  value: z.string().min(1).max(200),
});

export const SelectFieldSchema = z.object({
  ...baseField,
  type: z.literal("select"),
  defaultValue: z.string().optional(),
  options: z.array(optionSchema).min(1),
});

export const RadioFieldSchema = z.object({
  ...baseField,
  type: z.literal("radio"),
  defaultValue: z.string().optional(),
  options: z.array(optionSchema).min(1),
});

export const CheckboxFieldSchema = z.object({
  ...baseField,
  type: z.literal("checkbox"),
  defaultValue: z.boolean().optional(),
});

export const FieldConfigSchema = z.discriminatedUnion("type", [
  TextFieldSchema,
  TextareaFieldSchema,
  NumberFieldSchema,
  EmailFieldSchema,
  SelectFieldSchema,
  RadioFieldSchema,
  CheckboxFieldSchema,
]);

export const ToolConfigSchemaSchema = z.object({
  fields: z.array(FieldConfigSchema).default([]),
});

export type TextFieldConfig = z.infer<typeof TextFieldSchema>;
export type TextareaFieldConfig = z.infer<typeof TextareaFieldSchema>;
export type NumberFieldConfig = z.infer<typeof NumberFieldSchema>;
export type EmailFieldConfig = z.infer<typeof EmailFieldSchema>;
export type SelectFieldConfig = z.infer<typeof SelectFieldSchema>;
export type RadioFieldConfig = z.infer<typeof RadioFieldSchema>;
export type CheckboxFieldConfig = z.infer<typeof CheckboxFieldSchema>;
export type FieldConfig = z.infer<typeof FieldConfigSchema>;
export type ToolConfigSchema = z.infer<typeof ToolConfigSchemaSchema>;

import { ToolConfigSchemaSchema, type ToolConfigSchema } from "./schema";

const EMPTY_SCHEMA: ToolConfigSchema = { fields: [] };

/**
 * `tools.config_schema` is jsonb — Postgres guarantees it's valid JSON,
 * nothing about its shape. A malformed row (hand-edited in the SQL
 * editor, or written by a future admin tool with a bug) must never crash
 * the tool's page; it degrades to an empty form instead, same spirit as
 * lib/generation/plan.ts failing closed rather than open. The tool is
 * still usable (Stage 5's pipeline builds a generic prompt with no
 * template fields either way), just without configurable inputs until
 * the row is fixed.
 */
export function parseToolConfigSchema(raw: unknown): ToolConfigSchema {
  const result = ToolConfigSchemaSchema.safeParse(raw);
  if (!result.success) {
    console.error(
      "[tool-config] invalid config_schema, falling back to an empty form:",
      result.error.message,
    );
    return EMPTY_SCHEMA;
  }
  return result.data;
}

import type { FieldConfig, ToolConfigSchema } from "./schema";

/**
 * Client-side-only convenience, not a security boundary: it just avoids
 * spending an AI Provider Gateway call on a form that's obviously
 * incomplete. `/api/generate` (Stage 5) doesn't know or enforce per-tool
 * required fields — `inputParams` is a generic record as far as the
 * pipeline is concerned — so this has no server-side counterpart to stay
 * in sync with, and doesn't need one.
 */
export function findMissingRequiredFields(
  schema: ToolConfigSchema,
  values: Record<string, unknown>,
): string[] {
  return schema.fields
    .filter((field) => field.required && isEmptyValue(values[field.name], field.type))
    .map((field) => field.name);
}

function isEmptyValue(value: unknown, type: FieldConfig["type"]): boolean {
  if (type === "checkbox") return value !== true;
  if (typeof value === "number") return Number.isNaN(value);
  return value === undefined || value === null || value === "";
}

import "server-only";
import type { SupabaseClient } from "@supabase/supabase-js";
import type { Database } from "@/lib/supabase/database.types";
import type { ToolListItem } from "./types";

/**
 * The one place that lists active tools for browsing (the Tools Gallery).
 * This is a genuinely separate read from `lib/generation/catalog.ts`'s
 * `resolveTool()` — not a duplicate of it — because it answers a
 * different question for a different consumer:
 *
 *   resolveTool(slug)   → one tool, by slug, for /api/generate to build a
 *                          prompt with (id, name, configSchema — no
 *                          description/icon/category; the pipeline never
 *                          needed them).
 *   listActiveTools()   → every active tool, for the Gallery to render
 *                          cards from (slug, name, description, icon,
 *                          category — no id/configSchema; the Gallery
 *                          never needed those).
 *
 * Both read the same `tools` table through the same public-read RLS
 * policy (migration 0006, `is_active = true` for anon/authenticated) —
 * that policy is the single source of truth for "what counts as
 * available," reused here rather than re-implemented. Neither file
 * imports the other; there was nothing in `resolveTool()` this function
 * could have called without changing that function's return shape for a
 * caller (the pipeline) that never asked for one.
 */
export async function listActiveTools(
  supabase: SupabaseClient<Database>,
): Promise<ToolListItem[]> {
  const { data, error } = await supabase
    .from("tools")
    .select("slug, name, description, icon, category")
    .order("name", { ascending: true });

  if (error) {
    throw new ToolCatalogError("Failed to load tools.", error);
  }

  return (data ?? []).map((row) => ({
    slug: row.slug,
    name: row.name,
    description: row.description,
    icon: row.icon,
    category: row.category,
  }));
}

export class ToolCatalogError extends Error {
  constructor(
    message: string,
    public readonly cause?: unknown,
  ) {
    super(message);
    this.name = "ToolCatalogError";
  }
}

import type { ToolListItem } from "./types";

/**
 * Extensible now, not "extended later by editing this line" — widen this
 * union when a new sort actually ships (popularity needs a usage count
 * somewhere to sort by; newest/updated need created_at/updated_at on
 * ToolListItem, which it doesn't carry today because nothing renders
 * them yet). Adding one is: widen this type, add one branch in
 * `sortTools`, nothing in any component changes.
 */
export type ToolSortOption = "name";

export interface ToolQueryParams {
  search?: string;
  /** null/undefined = no category filter (show everything). */
  category?: string | null;
  sortBy?: ToolSortOption;
}

/**
 * The boundary Stage 7's "move search to the server later without
 * rewriting components" requirement is built around. Every caller
 * (ToolGallery today) passes the *same* `{ tools, params }` shape it
 * would pass to a server version of this function — swapping the body
 * for `await fetch("/api/tools?...")` later is a change to this one
 * file, not to ToolGallery, SearchBar, CategoryFilter, or ToolCard.
 *
 * Runs in memory deliberately for now: Stage 7's own scope note says so
 * explicitly ("if the dataset is small, search/filter may run in
 * memory"), and the current catalog is a handful of rows fetched in one
 * request by `listActiveTools()` — there's nothing to optimize yet.
 */
export function queryTools(tools: ToolListItem[], params: ToolQueryParams): ToolListItem[] {
  let result = tools;

  const search = params.search?.trim().toLowerCase();
  if (search) {
    result = result.filter(
      (tool) =>
        tool.name.toLowerCase().includes(search) ||
        (tool.description ?? "").toLowerCase().includes(search),
    );
  }

  if (params.category) {
    result = result.filter((tool) => tool.category === params.category);
  }

  return sortTools(result, params.sortBy ?? "name");
}

function sortTools(tools: ToolListItem[], sortBy: ToolSortOption): ToolListItem[] {
  const sorted = [...tools];

  switch (sortBy) {
    case "name":
      sorted.sort((a, b) => a.name.localeCompare(b.name));
      break;
  }

  return sorted;
}

/**
 * Categories are never a hand-maintained list — they're whatever distinct
 * `category` values actually exist in the data right now. A new category
 * appearing in the `tools` table (any future stage, no code change) shows
 * up here automatically the next time this runs.
 */
export function deriveCategories(tools: ToolListItem[]): string[] {
  const categories = new Set<string>();
  for (const tool of tools) {
    if (tool.category) categories.add(tool.category);
  }
  return Array.from(categories).sort((a, b) => a.localeCompare(b));
}

/**
 * Shape the Tools Gallery renders against. A deliberate subset of the
 * `tools` row — exactly the six fields Stage 7 named (slug, name,
 * description, icon, category, is_active), minus `is_active` itself:
 * the RLS policy on `tools` (migration 0006) already filters to
 * `is_active = true` for anyone without elevated access, so a row this
 * type describes is *always* active by construction. Carrying the flag
 * here would invite a component to branch on it redundantly.
 */
export interface ToolListItem {
  slug: string;
  name: string;
  description: string | null;
  icon: string | null;
  category: string | null;
}

// Minimal service worker foundation — install/activate only, no caching
// strategy yet (deliberately, per Stage 1 scope: "no full offline logic").
// A real cache strategy (network-first for /api, stale-while-revalidate for
// static assets) is added once there's real content worth caching.

self.addEventListener("install", (event) => {
  self.skipWaiting();
});

self.addEventListener("activate", (event) => {
  event.waitUntil(self.clients.claim());
});

self.addEventListener("fetch", () => {
  // Pass-through for now — intentionally not intercepting requests yet.
});

-- ============================================================ -- AI Marketing Workspace — full schema (through Stage 7) -- Generated by concatenating the structural migrations in order. -- Source of truth is migrations/*.sql — if you edit the schema, -- edit the numbered migration file and regenerate this, not the -- other way around. -- -- Paste this whole file into Supabase Dashboard → SQL Editor and -- run it once. Then run seed.sql. See supabase/README.md. -- -- Already ran the Stage 3/5 version of this file? You only need -- the new part: migrations/0012_tools_gallery_fields.sql, -- then migrations/0013_tools_gallery_seed_update.sql. -- ============================================================
-- ---------- migrations/0001_extensions_and_helpers.sql ---------- -- Stage 3: extensions and shared helpers used by every later migration.
-- UUID generation for primary keys. create extension if not exists "pgcrypto" with schema extensions;
-- Generic "bump updated_at on every UPDATE" trigger helper, ships with -- Supabase Postgres. Used instead of a hand-rolled trigger function so -- every table gets identical, well-tested behavior. create extension if not exists "moddatetime" schema extensions;
-- ---------- migrations/0002_plans_and_plan_limits.sql ---------- -- Plans and their limits. Created before `users` (migration 3) because -- `users.plan_id` references `plans(id)` — reference/billing tables have -- to exist before anything that points at them.
create table public.plans ( id uuid primary key default extensions.gen_random_uuid(), slug text not null unique check (slug in ('free', 'pro', 'enterprise')), name text not null, price_month numeric(10, 2) check (price_month is null or price_month >= 0), is_active boolean not null default true, created_at timestamptz not null default now(), updated_at timestamptz not null default now() );
create trigger set_updated_at before update on public.plans for each row execute procedure extensions.moddatetime(updated_at);
create table public.plan_limits ( id uuid primary key default extensions.gen_random_uuid(), plan_id uuid not null unique references public.plans(id) on delete cascade, -- null = unlimited, in every *_per_month / max_* column below. max_generations_per_month integer check (max_generations_per_month is null or max_generations_per_month >= 0), max_saved_results integer check (max_saved_results is null or max_saved_results >= 0), max_company_profiles integer default 1 check (max_company_profiles is null or max_company_profiles >= 1), -- "all" (jsonb string) or a jsonb array of tool/model slugs. allowed_tool_ids jsonb not null default '"all"'::jsonb, allowed_ai_models jsonb not null default '"all"'::jsonb, created_at timestamptz not null default now(), updated_at timestamptz not null default now() );
create trigger set_updated_at before update on public.plan_limits for each row execute procedure extensions.moddatetime(updated_at);
-- Reference/pricing data — safe to expose to anyone, logged in or not -- (a pricing page needs this before signup). No write policies: plans and -- their limits are only ever changed by hand in the SQL editor or by a -- future admin tool, never by application code. alter table public.plans enable row level security; alter table public.plan_limits enable row level security;
create policy "plans are publicly readable" on public.plans for select to anon, authenticated using (is_active = true);
create policy "plan_limits are publicly readable" on public.plan_limits for select to anon, authenticated using (true);
-- ---------- migrations/0003_users.sql ---------- -- Mirrors auth.users 1:1. Supabase's own auth.users table is in a -- protected schema the client can't query under RLS in a useful way, and -- we need a place to hang app-specific columns (plan_id) and a stable -- `public` row for every FK in the rest of the schema to point at. -- -- Populated by a trigger on auth.users (migration 0009, after every table -- it touches — plans and subscriptions — exists), not here.
create table public.users ( id uuid primary key references auth.users(id) on delete cascade, email text not null, plan_id uuid references public.plans(id) on delete set null, created_at timestamptz not null default now(), updated_at timestamptz not null default now() );
create index users_plan_id_idx on public.users(plan_id);
create trigger set_updated_at before update on public.users for each row execute procedure extensions.moddatetime(updated_at);
alter table public.users enable row level security;
-- A user can see and edit their own row only. There is deliberately no -- INSERT policy — rows are created exclusively by the `handle_new_user` -- trigger (SECURITY DEFINER, migration 0009), never by client code, so a -- signed-in user can never insert an arbitrary row for another id. create policy "users can view own row" on public.users for select to authenticated using (auth.uid() = id);
create policy "users can update own row" on public.users for update to authenticated using (auth.uid() = id) with check (auth.uid() = id);
-- ---------- migrations/0004_company_profiles.sql ---------- -- One user can hold more than one company profile (agencies managing -- several clients — see plan_limits.max_company_profiles and the project -- architecture doc §11 "not rushing team roles into MVP, but the schema -- should allow it"). No uniqueness constraint on user_id: that's the -- concrete expression of that decision.
create table public.company_profiles ( id uuid primary key default extensions.gen_random_uuid(), user_id uuid not null references public.users(id) on delete cascade, name text not null, niche text, tone_of_voice text, target_audience text, usp text, website_url text, logo_url text, created_at timestamptz not null default now(), updated_at timestamptz not null default now() );
create index company_profiles_user_id_idx on public.company_profiles(user_id);
create trigger set_updated_at before update on public.company_profiles for each row execute procedure extensions.moddatetime(updated_at);
alter table public.company_profiles enable row level security;
-- Full CRUD scoped to the owning user — Stage 12 (Company Profile screen) -- can read/write this directly from a Server Action or the browser client -- without a dedicated API route; RLS is the only gate it needs. create policy "users can view own company profiles" on public.company_profiles for select to authenticated using (auth.uid() = user_id);
create policy "users can insert own company profiles" on public.company_profiles for insert to authenticated with check (auth.uid() = user_id);
create policy "users can update own company profiles" on public.company_profiles for update to authenticated using (auth.uid() = user_id) with check (auth.uid() = user_id);
create policy "users can delete own company profiles" on public.company_profiles for delete to authenticated using (auth.uid() = user_id);
-- ---------- migrations/0005_guest_sessions.sql ---------- -- Guest sessions have no auth.uid() to key RLS off of — a guest is, by -- definition, not authenticated. Rather than build a workaround (e.g. -- trusting a session_token passed as a query param, which anyone could -- guess or intercept), this table gets RLS enabled with NO policies at -- all: that makes it default-deny for both `anon` and `authenticated` -- roles, full stop. The only way in is the service-role key, which -- bypasses RLS entirely and is only ever used from trusted server code -- (Stage 5's /api/generate, Stage 11's merge logic) — never shipped to -- the browser. This is the safest option available for unauthenticated -- state, not a placeholder to revisit.
create table public.guest_sessions ( id uuid primary key default extensions.gen_random_uuid(), session_token text not null unique, company_profile_draft jsonb, created_at timestamptz not null default now(), expires_at timestamptz not null, updated_at timestamptz not null default now() );
-- Session_token lookups (every read) and the TTL cleanup job (Stage 5+) -- both need their own index; the unique constraint above already gives -- session_token one for free. create index guest_sessions_expires_at_idx on public.guest_sessions(expires_at);
create trigger set_updated_at before update on public.guest_sessions for each row execute procedure extensions.moddatetime(updated_at);
alter table public.guest_sessions enable row level security; -- No policies — see comment above.
-- ---------- migrations/0006_tools_and_templates.sql ---------- -- Reference data that drives the whole "add a tool = a config row, not a -- deploy" mechanism (project architecture doc §7/§14). Public read-only — -- both guests and signed-in users need to see the Tools Gallery and -- Templates Library before/without registering.
create table public.tools ( id uuid primary key default extensions.gen_random_uuid(), slug text not null unique, name text not null, config_schema jsonb not null default '{}'::jsonb, is_active boolean not null default true, created_at timestamptz not null default now(), updated_at timestamptz not null default now() );
create trigger set_updated_at before update on public.tools for each row execute procedure extensions.moddatetime(updated_at);
create table public.templates ( id uuid primary key default extensions.gen_random_uuid(), tool_id uuid not null references public.tools(id) on delete cascade, slug text not null unique, name text not null, category text not null, prompt_template text not null default '', required_fields jsonb not null default '[]'::jsonb, is_premium boolean not null default false, created_at timestamptz not null default now(), updated_at timestamptz not null default now() );
create index templates_tool_id_idx on public.templates(tool_id); create index templates_category_idx on public.templates(category);
create trigger set_updated_at before update on public.templates for each row execute procedure extensions.moddatetime(updated_at);
alter table public.tools enable row level security; alter table public.templates enable row level security;
create policy "active tools are publicly readable" on public.tools for select to anon, authenticated using (is_active = true);
create policy "templates are publicly readable" on public.templates for select to anon, authenticated using (true);
-- No write policies on either table: managed by hand via the SQL editor -- (or a future admin tool) only, per the "config, not code" principle — -- application code only ever reads these.
-- ---------- migrations/0007_usage_and_subscriptions.sql ---------- -- Usage counters and billing status. Both are trusted-write-only: no -- INSERT/UPDATE/DELETE policy exists for `authenticated` on either table. -- If a client could increment its own usage_counters row, plan limits -- would be decorative. Writes happen exclusively from server code using -- the service-role client (Stage 5 for usage_counters on every -- generation, a future Stripe webhook for subscriptions) — SELECT is -- still open to the owning user so a usage indicator / billing page can -- read this directly without a dedicated API route.
create table public.usage_counters ( id uuid primary key default extensions.gen_random_uuid(), user_id uuid not null references public.users(id) on delete cascade, period_start date not null, period_end date not null, generations_count integer not null default 0 check (generations_count >= 0), created_at timestamptz not null default now(), updated_at timestamptz not null default now(), constraint usage_counters_period_valid check (period_end > period_start), constraint usage_counters_user_period_unique unique (user_id, period_start) );
create index usage_counters_user_id_idx on public.usage_counters(user_id);
create trigger set_updated_at before update on public.usage_counters for each row execute procedure extensions.moddatetime(updated_at);
alter table public.usage_counters enable row level security;
create policy "users can view own usage" on public.usage_counters for select to authenticated using (auth.uid() = user_id);
create table public.subscriptions ( id uuid primary key default extensions.gen_random_uuid(), user_id uuid not null references public.users(id) on delete cascade, plan_id uuid not null references public.plans(id), status text not null default 'active' check (status in ('active', 'trialing', 'past_due', 'canceled')), provider_ref text, period_end timestamptz, created_at timestamptz not null default now(), updated_at timestamptz not null default now() );
create index subscriptions_user_id_idx on public.subscriptions(user_id); create index subscriptions_status_idx on public.subscriptions(status);
create trigger set_updated_at before update on public.subscriptions for each row execute procedure extensions.moddatetime(updated_at);
alter table public.subscriptions enable row level security;
create policy "users can view own subscription" on public.subscriptions for select to authenticated using (auth.uid() = user_id);
-- ---------- migrations/0008_generations.sql ---------- -- The core event table every AI tool writes to. Owned by exactly one of -- `user_id` / `guest_session_id` (enforced below), which is what makes -- the guest→user merge (Stage 11) a metadata UPDATE rather than a data -- copy: flipping guest_session_id to null and setting user_id on existing -- rows is enough, nothing needs to move.
create table public.generations ( id uuid primary key default extensions.gen_random_uuid(), user_id uuid references public.users(id) on delete cascade, guest_session_id uuid references public.guest_sessions(id) on delete cascade, company_profile_id uuid references public.company_profiles(id) on delete set null, tool_id uuid not null references public.tools(id), template_id uuid references public.templates(id) on delete set null, ai_provider text not null, ai_model text not null, input_params jsonb not null default '{}'::jsonb, output text not null default '', is_favorite boolean not null default false, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), constraint generations_owner_required check (user_id is not null or guest_session_id is not null) );
-- History screen (Stage 11) paginates a single user's rows newest-first — -- this is the index that query actually needs. create index generations_user_id_created_at_idx on public.generations(user_id, created_at desc); create index generations_guest_session_id_idx on public.generations(guest_session_id); create index generations_tool_id_idx on public.generations(tool_id);
create trigger set_updated_at before update on public.generations for each row execute procedure extensions.moddatetime(updated_at);
alter table public.generations enable row level security;
-- Scoped to the owning user. This is what lets Stage 5's /api/generate use -- the caller's own session-bound Supabase client (RLS-enforced) for -- signed-in requests instead of the service-role key — the privileged -- client is reserved for guest requests, which have no auth.uid() to -- scope a policy to (same reasoning as guest_sessions, migration 0005). create policy "users can view own generations" on public.generations for select to authenticated using (auth.uid() = user_id);
create policy "users can insert own generations" on public.generations for insert to authenticated with check (auth.uid() = user_id);
-- Scoped update, not just for "is_favorite": a client toggling one field -- on its own row is a normal, safe operation under RLS, and adding this -- now means Stage 11 (History screen, favorites) needs no new policy. create policy "users can update own generations" on public.generations for update to authenticated using (auth.uid() = user_id) with check (auth.uid() = user_id);
-- ---------- migrations/0009_auth_trigger.sql ---------- -- Auto-creates the public.users (+ starter subscription) row the moment -- Supabase Auth creates an auth.users row — i.e. right after signUp() -- (Stage 2). Defined last, not alongside `users` in migration 0003, -- because it writes to `public.subscriptions`, which doesn't exist until -- migration 0007 — a plpgsql function body isn't checked against table -- existence at CREATE time, but the trigger still shouldn't be *live* -- before every table it touches is. -- -- SECURITY DEFINER: runs with the privileges of the function's owner -- (postgres), not the invoking session — required because this fires -- inside Supabase's own auth flow, before the new user has any session -- for RLS to key off of.
create function public.handle_new_user() returns trigger language plpgsql security definer set search_path = public as $$ declare v_plan_id uuid; begin select id into v_plan_id from public.plans where slug = 'free' limit 1;
insert into public.users (id, email, plan_id) values (new.id, new.email, v_plan_id);
-- If the free plan hasn't been seeded yet, v_plan_id is null and the -- user is created with no plan rather than failing signup outright — -- degraded, not broken. Seeding (migration 0010) always runs before any -- real signup in practice, but the function doesn't assume it. if v_plan_id is not null then insert into public.subscriptions (user_id, plan_id, status) values (new.id, v_plan_id, 'active'); end if;
return new; end; $$;
create trigger on_auth_user_created after insert on auth.users for each row execute procedure public.handle_new_user();
-- ---------- migrations/0011_increment_usage_counter.sql ---------- -- Additive-only migration (Stage 5): one new function, no table changes. -- Not a schema redesign — the architecture approved in Stage 3 is -- untouched; this is the atomic-increment primitive that -- lib/generation/save.ts needs to update usage_counters safely under -- concurrent requests (two tabs, a client retry) without a lost update. -- -- A select-then-update from application code has a race: two concurrent -- requests can both read count=5, both write count=6, and one increment -- is silently lost — exactly the kind of bug that's invisible in testing -- and shows up as "my limit let me generate one more than it should have" -- in production. This function does the read-modify-write as a single -- atomic UPSERT instead.
create or replace function public.increment_usage_counter( p_user_id uuid, p_period_start date, p_period_end date ) returns public.usage_counters language plpgsql security definer set search_path = public as $$ declare v_row public.usage_counters; begin insert into public.usage_counters (user_id, period_start, period_end, generations_count) values (p_user_id, p_period_start, p_period_end, 1) on conflict (user_id, period_start) do update set generations_count = public.usage_counters.generations_count + 1 returning * into v_row;
return v_row; end; $$;
-- SECURITY DEFINER functions are exposed via PostgREST (and therefore -- callable by `anon`/`authenticated` through supabase-js .rpc()) by -- default, same as any other schema object — that would let a signed-in -- user call this directly and increment (or fabricate) their own usage -- row from the client, defeating the entire point of usage_counters -- having no client write policy (migration 0007). Explicitly revoking -- from anon/authenticated and granting only to service_role closes that -- gap; only the admin client (lib/supabase/admin.ts) can call this. revoke all on function public.increment_usage_counter(uuid, date, date) from public, anon, authenticated; grant execute on function public.increment_usage_counter(uuid, date, date) to service_role;
-- ---------- migrations/0012_tools_gallery_fields.sql ---------- -- Stage 7 (Tools Gallery) needs `tools.description`, `tools.icon`, and -- `tools.category` for cards, categories, and search — none of which -- existed in migration 0006. This wasn't an oversight to quietly patch: -- Stage 6 (ToolRunner) genuinely never needed them, so they weren't added -- until a real consumer (this stage) required them. Additive-only, same -- discipline as migration 0011 — no existing column touched, nothing -- Stage 1-6 depends on changes shape. -- -- All three nullable: existing seed rows (migration 0010) predate these -- columns, and a tool without a category/description/icon should degrade -- gracefully in the gallery (see components/tools/gallery/ToolCard.tsx), -- not be forced to backfill placeholder content it doesn't have yet.
alter table public.tools add column description text, add column icon text, add column category text;
-- Supports category filtering — in-memory today (Stage 7 scope: dataset -- is a handful of tools), but this is exactly the kind of index that -- costs nothing now and avoids a migration later if/when category -- filtering moves server-side, per the project architecture doc's -- general "cheap now, expensive later" indexing rationale (see the -- Stage 3 audit for company_profiles/generations precedent). create index tools_category_idx on public.tools(category);

-- ============================================================ -- AI Marketing Workspace — seed data (through Stage 9) -- Generated from migrations/0010, 0013, 0014, 0015. Run AFTER schema.sql. -- Safe to re-run any time (idempotent). -- ============================================================
-- ---------- migrations/0010_seed.sql ---------- -- Seed data for plans / plan_limits / tools. -- -- Values here are copied byte-for-byte from config/plans.json and -- config/tools.json (the pre-DB stand-ins from Stage 1/2) rather than -- invented fresh, specifically so the two don't drift apart. Once Stage 5+ -- switches application code to querying these tables directly, those JSON -- files stop being read at runtime — until then, both describe the same -- numbers on purpose. -- -- Idempotent: safe to re-run (e.g. after `supabase db reset`) via -- ON CONFLICT upserts, so this file never needs a companion "have I -- already seeded?" check. -- -- No template rows yet: config/templates.json ships 16 categories but zero -- concrete templates — real prompt_template content is Stage 10 scope. -- Seeding placeholder templates now would mean deleting or rewriting them -- later; better to leave the (already-created, indexed, RLS-protected) -- table empty until there's real content for it.
insert into public.plans (slug, name, price_month, is_active) values ('free', 'Free', 0, true), ('pro', 'Pro', 29, true), ('enterprise', 'Enterprise', null, true) on conflict (slug) do update set name = excluded.name, price_month = excluded.price_month, is_active = excluded.is_active;
insert into public.plan_limits ( plan_id, max_generations_per_month, max_saved_results, max_company_profiles, allowed_tool_ids, allowed_ai_models ) select p.id, v.max_generations_per_month, v.max_saved_results, v.max_company_profiles, v.allowed_tool_ids, v.allowed_ai_models from ( values ('free', 20, 20, 1, '["ad-generator", "email-generator", "social-generator"]'::jsonb, '["claude"]'::jsonb), ('pro', 500, null, 3, '"all"'::jsonb, '["claude", "openai", "gemini"]'::jsonb), ('enterprise', null, null, null, '"all"'::jsonb, '"all"'::jsonb) ) as v(slug, max_generations_per_month, max_saved_results, max_company_profiles, allowed_tool_ids, allowed_ai_models) join public.plans p on p.slug = v.slug on conflict (plan_id) do update set max_generations_per_month = excluded.max_generations_per_month, max_saved_results = excluded.max_saved_results, max_company_profiles = excluded.max_company_profiles, allowed_tool_ids = excluded.allowed_tool_ids, allowed_ai_models = excluded.allowed_ai_models;
-- is_active = false on all three: matches config/tools.json exactly — the -- tools exist as rows (so `generations.tool_id` and the Templates Library -- FK have something to point at) but stay hidden from the Tools Gallery -- until each is actually wired up (Stage 8-10), the same way the route -- placeholders from Stage 1 are reachable but not linked from anywhere yet. insert into public.tools (slug, name, is_active) values ('ad-generator', 'AI Ad Generator', false), ('email-generator', 'AI Email Generator', false), ('social-generator', 'AI Social Media Generator', false) on conflict (slug) do update set name = excluded.name, is_active = excluded.is_active;
-- ---------- migrations/0013_tools_gallery_seed_update.sql ---------- -- Backfills description/icon/category (migration 0012) onto the three -- tools seeded in migration 0010. Idempotent UPDATE, not a rewrite of the -- original seed INSERT — 0010 already ran; this only sets the new columns -- on the rows it created. Values are functional placeholders (accurate, -- minimal) — real per-tool copy is Stage 8-10 scope same as it always -- was; this migration exists only so the Gallery has something real to -- render against these three (still `is_active = false`, unchanged) rows -- rather than every field being empty.
update public.tools set description = 'Generate ready-to-run ad copy for your campaigns.', icon = '📣', category = 'Ads' where slug = 'ad-generator';
update public.tools set description = 'Draft marketing emails tailored to your audience.', icon = '✉️', category = 'Email' where slug = 'email-generator';
update public.tools set description = 'Create on-brand posts for your social channels.', icon = '📱', category = 'Social' where slug = 'social-generator';
-- ---------- migrations/0014_ad_generator_activation.sql ---------- -- Stage 8: the first real tool. Activates `ad-generator` (seeded inactive -- in migration 0010, category/description/icon added in 0013) with a -- real `config_schema` (format defined in Stage 6, -- lib/tool-config/schema.ts) and a real default template — the first -- content this project ships, not scaffold. -- -- Pure data (UPDATE + INSERT), no ALTER TABLE: Stage 3/6/7's schema -- already had everywhere this needed to write to -- (tools.config_schema jsonb, templates.prompt_template/required_fields) -- — worth noting as evidence that schema, not a gap this stage had to -- patch. -- -- Four fields, chosen for what an ad actually needs to be generated -- (platform, what's being advertised, an optional offer, a call to -- action) — not a UI/UX layout decision, a data requirement: the prompt -- template below literally can't produce a usable ad without knowing -- these. No fifth field ("tone") was added: the company profile already -- carries tone_of_voice into every prompt (lib/generation/prompt.ts, -- Stage 5) — a second, per-generation tone control would be redundant -- with data the pipeline already uses, not a missing feature.
update public.tools set is_active = true, config_schema = $json$ { "fields": [ { "type": "select", "name": "platform", "label": "Platform", "required": true, "options": [ { "label": "Facebook", "value": "Facebook" }, { "label": "Instagram", "value": "Instagram" }, { "label": "Google Search", "value": "Google Search" }, { "label": "LinkedIn", "value": "LinkedIn" }, { "label": "X (Twitter)", "value": "X (Twitter)" } ] }, { "type": "text", "name": "productOrService", "label": "Product or service being advertised", "required": true, "maxLength": 200 }, { "type": "textarea", "name": "offerDetails", "label": "Offer or promotion details", "helpText": "Optional — e.g. a discount, launch, or limited-time deal.", "required": false, "maxLength": 500, "rows": 3 }, { "type": "select", "name": "callToAction", "label": "Call to action", "required": true, "options": [ { "label": "Shop Now", "value": "Shop Now" }, { "label": "Learn More", "value": "Learn More" }, { "label": "Sign Up", "value": "Sign Up" }, { "label": "Get Started", "value": "Get Started" }, { "label": "Contact Us", "value": "Contact Us" } ] } ] } $json$::jsonb where slug = 'ad-generator';
-- One default template. `category` here is 'General' rather than a -- platform name (e.g. 'Facebook Ads') because `platform` is a field -- *within* this template, not a separate template per platform — it -- adapts to whichever platform the user picks, so it doesn't belong to -- one of the 16 platform-specific categories config/templates.json lists -- for the future Templates Library (Stage 10). Platform-specific -- templates, if wanted, are additional rows Stage 10 can add without -- touching this one. insert into public.templates (tool_id, slug, name, category, prompt_template, required_fields, is_premium) select id, 'ad-generator-default', 'Standard Ad', 'General', $prompt$Write a single, ready-to-publish ad for {{platform}}.
Product or service: {{productOrService}} Offer or promotion: {{offerDetails}} Call to action: {{callToAction}}
Follow {{platform}}'s typical ad copy length and conventions. Output only the ad copy itself — no explanations, no headers, no surrounding quotation marks.$prompt$, '["platform", "productOrService", "callToAction"]'::jsonb, false from public.tools where slug = 'ad-generator' on conflict (slug) do update set tool_id = excluded.tool_id, name = excluded.name, category = excluded.category, prompt_template = excluded.prompt_template, required_fields = excluded.required_fields, is_premium = excluded.is_premium;
-- ---------- migrations/0015_email_and_social_generator_activation.sql ---------- -- Stage 9: second and third tools, via the exact same mechanism as -- migration 0014 (Stage 8) — pure data (UPDATE tools + INSERT templates), -- zero ALTER TABLE, zero application code changes. That absence of code -- changes is not an oversight; it is Stage 9's actual deliverable, per -- the brief: proof that lib/generation/catalog.ts, ToolRunner, -- ToolGallery, and lib/tools/query.ts are genuinely tool-agnostic, not -- ad-generator-shaped code that happens to work once. Nothing in this -- file requires any of those to change. -- -- Both tools follow the same 4-field shape Stage 8 established -- (type/topic-of-content, an optional offer, a required call to action) -- — that shape is repeated here because it's what any short promotional -- copy generator objectively needs, not because it was copied for -- consistency's sake. `offerDetails` and `callToAction` reuse the exact -- field names from ad-generator's schema where the concept is genuinely -- identical (an optional offer, a call-to-action choice); `emailType`/ -- `platform` and `productOrTopic`/`contentTopic` are named for what each -- tool actually asks, not forced to match ad-generator's -- `productOrService` — there is no shared code reading these keys across -- tools, so there is nothing to keep artificially uniform, and -- ad-generator's own (already-shipped, Stage 8) data is not touched here.
update public.tools set is_active = true, config_schema = $json$ { "fields": [ { "type": "select", "name": "emailType", "label": "Email type", "required": true, "options": [ { "label": "Promotional", "value": "Promotional" }, { "label": "Newsletter", "value": "Newsletter" }, { "label": "Announcement", "value": "Announcement" }, { "label": "Welcome email", "value": "Welcome email" }, { "label": "Re-engagement", "value": "Re-engagement" } ] }, { "type": "text", "name": "productOrTopic", "label": "What is this email about?", "required": true, "maxLength": 200 }, { "type": "textarea", "name": "offerDetails", "label": "Offer or key message", "helpText": "Optional — e.g. a discount, launch, or update worth highlighting.", "required": false, "maxLength": 500, "rows": 3 }, { "type": "select", "name": "callToAction", "label": "Call to action", "required": true, "options": [ { "label": "Shop Now", "value": "Shop Now" }, { "label": "Learn More", "value": "Learn More" }, { "label": "Sign Up", "value": "Sign Up" }, { "label": "Book a Call", "value": "Book a Call" }, { "label": "Reply to This Email", "value": "Reply to This Email" } ] } ] } $json$::jsonb where slug = 'email-generator';
update public.tools set is_active = true, config_schema = $json$ { "fields": [ { "type": "select", "name": "platform", "label": "Platform", "required": true, "options": [ { "label": "Instagram", "value": "Instagram" }, { "label": "Facebook", "value": "Facebook" }, { "label": "LinkedIn", "value": "LinkedIn" }, { "label": "X (Twitter)", "value": "X (Twitter)" }, { "label": "TikTok", "value": "TikTok" } ] }, { "type": "text", "name": "contentTopic", "label": "What is this post about?", "required": true, "maxLength": 200 }, { "type": "textarea", "name": "offerDetails", "label": "Offer or key message", "helpText": "Optional — e.g. a discount, launch, or update worth highlighting.", "required": false, "maxLength": 500, "rows": 3 }, { "type": "select", "name": "callToAction", "label": "Call to action", "required": true, "options": [ { "label": "Shop Now", "value": "Shop Now" }, { "label": "Learn More", "value": "Learn More" }, { "label": "Follow Us", "value": "Follow Us" }, { "label": "Sign Up", "value": "Sign Up" }, { "label": "Comment Below", "value": "Comment Below" } ] } ] } $json$::jsonb where slug = 'social-generator';
-- Both templates: category 'General', same reasoning as ad-generator's -- (migration 0014) — each adapts to whichever email type / platform the -- user picks via its own field, so neither belongs to one of the 16 -- platform-specific categories config/templates.json lists for the -- future Templates Library (Stage 10).
insert into public.templates (tool_id, slug, name, category, prompt_template, required_fields, is_premium) select id, 'email-generator-default', 'Standard Email', 'General', $prompt$Write a single, ready-to-send marketing email.
Email type: {{emailType}} Topic: {{productOrTopic}} Offer or key message: {{offerDetails}} Call to action: {{callToAction}}
Start with a subject line on its own line prefixed "Subject: ", then a blank line, then the email body. Output only that — no explanations, no extra commentary, no surrounding quotation marks.$prompt$, '["emailType", "productOrTopic", "callToAction"]'::jsonb, false from public.tools where slug = 'email-generator' on conflict (slug) do update set tool_id = excluded.tool_id, name = excluded.name, category = excluded.category, prompt_template = excluded.prompt_template, required_fields = excluded.required_fields, is_premium = excluded.is_premium;
insert into public.templates (tool_id, slug, name, category, prompt_template, required_fields, is_premium) select id, 'social-generator-default', 'Standard Social Post', 'General', $prompt$Write a single, ready-to-publish social media post for {{platform}}.
Topic: {{contentTopic}} Offer or key message: {{offerDetails}} Call to action: {{callToAction}}
Follow {{platform}}'s typical length, tone and hashtag conventions. Output only the post itself — no explanations, no headers, no surrounding quotation marks.$prompt$, '["platform", "contentTopic", "callToAction"]'::jsonb, false from public.tools where slug = 'social-generator' on conflict (slug) do update set tool_id = excluded.tool_id, name = excluded.name, category = excluded.category, prompt_template = excluded.prompt_template, required_fields = excluded.required_fields, is_premium = excluded.is_premium;

-- Stage 3: extensions and shared helpers used by every later migration.
-- UUID generation for primary keys. create extension if not exists "pgcrypto" with schema extensions;
-- Generic "bump updated_at on every UPDATE" trigger helper, ships with -- Supabase Postgres. Used instead of a hand-rolled trigger function so -- every table gets identical, well-tested behavior. create extension if not exists "moddatetime" schema extensions;

-- Plans and their limits. Created before `users` (migration 3) because -- `users.plan_id` references `plans(id)` — reference/billing tables have -- to exist before anything that points at them.
create table public.plans ( id uuid primary key default extensions.gen_random_uuid(), slug text not null unique check (slug in ('free', 'pro', 'enterprise')), name text not null, price_month numeric(10, 2) check (price_month is null or price_month >= 0), is_active boolean not null default true, created_at timestamptz not null default now(), updated_at timestamptz not null default now() );
create trigger set_updated_at before update on public.plans for each row execute procedure extensions.moddatetime(updated_at);
create table public.plan_limits ( id uuid primary key default extensions.gen_random_uuid(), plan_id uuid not null unique references public.plans(id) on delete cascade, -- null = unlimited, in every *_per_month / max_* column below. max_generations_per_month integer check (max_generations_per_month is null or max_generations_per_month >= 0), max_saved_results integer check (max_saved_results is null or max_saved_results >= 0), max_company_profiles integer default 1 check (max_company_profiles is null or max_company_profiles >= 1), -- "all" (jsonb string) or a jsonb array of tool/model slugs. allowed_tool_ids jsonb not null default '"all"'::jsonb, allowed_ai_models jsonb not null default '"all"'::jsonb, created_at timestamptz not null default now(), updated_at timestamptz not null default now() );
create trigger set_updated_at before update on public.plan_limits for each row execute procedure extensions.moddatetime(updated_at);
-- Reference/pricing data — safe to expose to anyone, logged in or not -- (a pricing page needs this before signup). No write policies: plans and -- their limits are only ever changed by hand in the SQL editor or by a -- future admin tool, never by application code. alter table public.plans enable row level security; alter table public.plan_limits enable row level security;
create policy "plans are publicly readable" on public.plans for select to anon, authenticated using (is_active = true);
create policy "plan_limits are publicly readable" on public.plan_limits for select to anon, authenticated using (true);

-- Mirrors auth.users 1:1. Supabase's own auth.users table is in a -- protected schema the client can't query under RLS in a useful way, and -- we need a place to hang app-specific columns (plan_id) and a stable -- `public` row for every FK in the rest of the schema to point at. -- -- Populated by a trigger on auth.users (migration 0009, after every table -- it touches — plans and subscriptions — exists), not here.
create table public.users ( id uuid primary key references auth.users(id) on delete cascade, email text not null, plan_id uuid references public.plans(id) on delete set null, created_at timestamptz not null default now(), updated_at timestamptz not null default now() );
create index users_plan_id_idx on public.users(plan_id);
create trigger set_updated_at before update on public.users for each row execute procedure extensions.moddatetime(updated_at);
alter table public.users enable row level security;
-- A user can see and edit their own row only. There is deliberately no -- INSERT policy — rows are created exclusively by the `handle_new_user` -- trigger (SECURITY DEFINER, migration 0009), never by client code, so a -- signed-in user can never insert an arbitrary row for another id. create policy "users can view own row" on public.users for select to authenticated using (auth.uid() = id);
create policy "users can update own row" on public.users for update to authenticated using (auth.uid() = id) with check (auth.uid() = id);

-- One user can hold more than one company profile (agencies managing -- several clients — see plan_limits.max_company_profiles and the project -- architecture doc §11 "not rushing team roles into MVP, but the schema -- should allow it"). No uniqueness constraint on user_id: that's the -- concrete expression of that decision.
create table public.company_profiles ( id uuid primary key default extensions.gen_random_uuid(), user_id uuid not null references public.users(id) on delete cascade, name text not null, niche text, tone_of_voice text, target_audience text, usp text, website_url text, logo_url text, created_at timestamptz not null default now(), updated_at timestamptz not null default now() );
create index company_profiles_user_id_idx on public.company_profiles(user_id);
create trigger set_updated_at before update on public.company_profiles for each row execute procedure extensions.moddatetime(updated_at);
alter table public.company_profiles enable row level security;
-- Full CRUD scoped to the owning user — Stage 12 (Company Profile screen) -- can read/write this directly from a Server Action or the browser client -- without a dedicated API route; RLS is the only gate it needs. create policy "users can view own company profiles" on public.company_profiles for select to authenticated using (auth.uid() = user_id);
create policy "users can insert own company profiles" on public.company_profiles for insert to authenticated with check (auth.uid() = user_id);
create policy "users can update own company profiles" on public.company_profiles for update to authenticated using (auth.uid() = user_id) with check (auth.uid() = user_id);
create policy "users can delete own company profiles" on public.company_profiles for delete to authenticated using (auth.uid() = user_id);

-- Guest sessions have no auth.uid() to key RLS off of — a guest is, by -- definition, not authenticated. Rather than build a workaround (e.g. -- trusting a session_token passed as a query param, which anyone could -- guess or intercept), this table gets RLS enabled with NO policies at -- all: that makes it default-deny for both `anon` and `authenticated` -- roles, full stop. The only way in is the service-role key, which -- bypasses RLS entirely and is only ever used from trusted server code -- (Stage 5's /api/generate, Stage 11's merge logic) — never shipped to -- the browser. This is the safest option available for unauthenticated -- state, not a placeholder to revisit.
create table public.guest_sessions ( id uuid primary key default extensions.gen_random_uuid(), session_token text not null unique, company_profile_draft jsonb, created_at timestamptz not null default now(), expires_at timestamptz not null, updated_at timestamptz not null default now() );
-- Session_token lookups (every read) and the TTL cleanup job (Stage 5+) -- both need their own index; the unique constraint above already gives -- session_token one for free. create index guest_sessions_expires_at_idx on public.guest_sessions(expires_at);
create trigger set_updated_at before update on public.guest_sessions for each row execute procedure extensions.moddatetime(updated_at);
alter table public.guest_sessions enable row level security; -- No policies — see comment above.

-- Reference data that drives the whole "add a tool = a config row, not a -- deploy" mechanism (project architecture doc §7/§14). Public read-only — -- both guests and signed-in users need to see the Tools Gallery and -- Templates Library before/without registering.
create table public.tools ( id uuid primary key default extensions.gen_random_uuid(), slug text not null unique, name text not null, config_schema jsonb not null default '{}'::jsonb, is_active boolean not null default true, created_at timestamptz not null default now(), updated_at timestamptz not null default now() );
create trigger set_updated_at before update on public.tools for each row execute procedure extensions.moddatetime(updated_at);
create table public.templates ( id uuid primary key default extensions.gen_random_uuid(), tool_id uuid not null references public.tools(id) on delete cascade, slug text not null unique, name text not null, category text not null, prompt_template text not null default '', required_fields jsonb not null default '[]'::jsonb, is_premium boolean not null default false, created_at timestamptz not null default now(), updated_at timestamptz not null default now() );
create index templates_tool_id_idx on public.templates(tool_id); create index templates_category_idx on public.templates(category);
create trigger set_updated_at before update on public.templates for each row execute procedure extensions.moddatetime(updated_at);
alter table public.tools enable row level security; alter table public.templates enable row level security;
create policy "active tools are publicly readable" on public.tools for select to anon, authenticated using (is_active = true);
create policy "templates are publicly readable" on public.templates for select to anon, authenticated using (true);
-- No write policies on either table: managed by hand via the SQL editor -- (or a future admin tool) only, per the "config, not code" principle — -- application code only ever reads these.

-- Usage counters and billing status. Both are trusted-write-only: no -- INSERT/UPDATE/DELETE policy exists for `authenticated` on either table. -- If a client could increment its own usage_counters row, plan limits -- would be decorative. Writes happen exclusively from server code using -- the service-role client (Stage 5 for usage_counters on every -- generation, a future Stripe webhook for subscriptions) — SELECT is -- still open to the owning user so a usage indicator / billing page can -- read this directly without a dedicated API route.
create table public.usage_counters ( id uuid primary key default extensions.gen_random_uuid(), user_id uuid not null references public.users(id) on delete cascade, period_start date not null, period_end date not null, generations_count integer not null default 0 check (generations_count >= 0), created_at timestamptz not null default now(), updated_at timestamptz not null default now(), constraint usage_counters_period_valid check (period_end > period_start), constraint usage_counters_user_period_unique unique (user_id, period_start) );
create index usage_counters_user_id_idx on public.usage_counters(user_id);
create trigger set_updated_at before update on public.usage_counters for each row execute procedure extensions.moddatetime(updated_at);
alter table public.usage_counters enable row level security;
create policy "users can view own usage" on public.usage_counters for select to authenticated using (auth.uid() = user_id);
create table public.subscriptions ( id uuid primary key default extensions.gen_random_uuid(), user_id uuid not null references public.users(id) on delete cascade, plan_id uuid not null references public.plans(id), status text not null default 'active' check (status in ('active', 'trialing', 'past_due', 'canceled')), provider_ref text, period_end timestamptz, created_at timestamptz not null default now(), updated_at timestamptz not null default now() );
create index subscriptions_user_id_idx on public.subscriptions(user_id); create index subscriptions_status_idx on public.subscriptions(status);
create trigger set_updated_at before update on public.subscriptions for each row execute procedure extensions.moddatetime(updated_at);
alter table public.subscriptions enable row level security;
create policy "users can view own subscription" on public.subscriptions for select to authenticated using (auth.uid() = user_id);

-- The core event table every AI tool writes to. Owned by exactly one of -- `user_id` / `guest_session_id` (enforced below), which is what makes -- the guest→user merge (Stage 11) a metadata UPDATE rather than a data -- copy: flipping guest_session_id to null and setting user_id on existing -- rows is enough, nothing needs to move.
create table public.generations ( id uuid primary key default extensions.gen_random_uuid(), user_id uuid references public.users(id) on delete cascade, guest_session_id uuid references public.guest_sessions(id) on delete cascade, company_profile_id uuid references public.company_profiles(id) on delete set null, tool_id uuid not null references public.tools(id), template_id uuid references public.templates(id) on delete set null, ai_provider text not null, ai_model text not null, input_params jsonb not null default '{}'::jsonb, output text not null default '', is_favorite boolean not null default false, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), constraint generations_owner_required check (user_id is not null or guest_session_id is not null) );
-- History screen (Stage 11) paginates a single user's rows newest-first — -- this is the index that query actually needs. create index generations_user_id_created_at_idx on public.generations(user_id, created_at desc); create index generations_guest_session_id_idx on public.generations(guest_session_id); create index generations_tool_id_idx on public.generations(tool_id);
create trigger set_updated_at before update on public.generations for each row execute procedure extensions.moddatetime(updated_at);
alter table public.generations enable row level security;
-- Scoped to the owning user. This is what lets Stage 5's /api/generate use -- the caller's own session-bound Supabase client (RLS-enforced) for -- signed-in requests instead of the service-role key — the privileged -- client is reserved for guest requests, which have no auth.uid() to -- scope a policy to (same reasoning as guest_sessions, migration 0005). create policy "users can view own generations" on public.generations for select to authenticated using (auth.uid() = user_id);
create policy "users can insert own generations" on public.generations for insert to authenticated with check (auth.uid() = user_id);
-- Scoped update, not just for "is_favorite": a client toggling one field -- on its own row is a normal, safe operation under RLS, and adding this -- now means Stage 11 (History screen, favorites) needs no new policy. create policy "users can update own generations" on public.generations for update to authenticated using (auth.uid() = user_id) with check (auth.uid() = user_id);

-- Auto-creates the public.users (+ starter subscription) row the moment -- Supabase Auth creates an auth.users row — i.e. right after signUp() -- (Stage 2). Defined last, not alongside `users` in migration 0003, -- because it writes to `public.subscriptions`, which doesn't exist until -- migration 0007 — a plpgsql function body isn't checked against table -- existence at CREATE time, but the trigger still shouldn't be *live* -- before every table it touches is. -- -- SECURITY DEFINER: runs with the privileges of the function's owner -- (postgres), not the invoking session — required because this fires -- inside Supabase's own auth flow, before the new user has any session -- for RLS to key off of.
create function public.handle_new_user() returns trigger language plpgsql security definer set search_path = public as $$ declare v_plan_id uuid; begin select id into v_plan_id from public.plans where slug = 'free' limit 1;
insert into public.users (id, email, plan_id) values (new.id, new.email, v_plan_id);
-- If the free plan hasn't been seeded yet, v_plan_id is null and the -- user is created with no plan rather than failing signup outright — -- degraded, not broken. Seeding (migration 0010) always runs before any -- real signup in practice, but the function doesn't assume it. if v_plan_id is not null then insert into public.subscriptions (user_id, plan_id, status) values (new.id, v_plan_id, 'active'); end if;
return new; end; $$;
create trigger on_auth_user_created after insert on auth.users for each row execute procedure public.handle_new_user();

-- Seed data for plans / plan_limits / tools. -- -- Values here are copied byte-for-byte from config/plans.json and -- config/tools.json (the pre-DB stand-ins from Stage 1/2) rather than -- invented fresh, specifically so the two don't drift apart. Once Stage 5+ -- switches application code to querying these tables directly, those JSON -- files stop being read at runtime — until then, both describe the same -- numbers on purpose. -- -- Idempotent: safe to re-run (e.g. after `supabase db reset`) via -- ON CONFLICT upserts, so this file never needs a companion "have I -- already seeded?" check. -- -- No template rows yet: config/templates.json ships 16 categories but zero -- concrete templates — real prompt_template content is Stage 10 scope. -- Seeding placeholder templates now would mean deleting or rewriting them -- later; better to leave the (already-created, indexed, RLS-protected) -- table empty until there's real content for it.
insert into public.plans (slug, name, price_month, is_active) values ('free', 'Free', 0, true), ('pro', 'Pro', 29, true), ('enterprise', 'Enterprise', null, true) on conflict (slug) do update set name = excluded.name, price_month = excluded.price_month, is_active = excluded.is_active;
insert into public.plan_limits ( plan_id, max_generations_per_month, max_saved_results, max_company_profiles, allowed_tool_ids, allowed_ai_models ) select p.id, v.max_generations_per_month, v.max_saved_results, v.max_company_profiles, v.allowed_tool_ids, v.allowed_ai_models from ( values ('free', 20, 20, 1, '["ad-generator", "email-generator", "social-generator"]'::jsonb, '["claude"]'::jsonb), ('pro', 500, null, 3, '"all"'::jsonb, '["claude", "openai", "gemini"]'::jsonb), ('enterprise', null, null, null, '"all"'::jsonb, '"all"'::jsonb) ) as v(slug, max_generations_per_month, max_saved_results, max_company_profiles, allowed_tool_ids, allowed_ai_models) join public.plans p on p.slug = v.slug on conflict (plan_id) do update set max_generations_per_month = excluded.max_generations_per_month, max_saved_results = excluded.max_saved_results, max_company_profiles = excluded.max_company_profiles, allowed_tool_ids = excluded.allowed_tool_ids, allowed_ai_models = excluded.allowed_ai_models;
-- is_active = false on all three: matches config/tools.json exactly — the -- tools exist as rows (so `generations.tool_id` and the Templates Library -- FK have something to point at) but stay hidden from the Tools Gallery -- until each is actually wired up (Stage 8-10), the same way the route -- placeholders from Stage 1 are reachable but not linked from anywhere yet. insert into public.tools (slug, name, is_active) values ('ad-generator', 'AI Ad Generator', false), ('email-generator', 'AI Email Generator', false), ('social-generator', 'AI Social Media Generator', false) on conflict (slug) do update set name = excluded.name, is_active = excluded.is_active;

-- Additive-only migration (Stage 5): one new function, no table changes. -- Not a schema redesign — the architecture approved in Stage 3 is -- untouched; this is the atomic-increment primitive that -- lib/generation/save.ts needs to update usage_counters safely under -- concurrent requests (two tabs, a client retry) without a lost update. -- -- A select-then-update from application code has a race: two concurrent -- requests can both read count=5, both write count=6, and one increment -- is silently lost — exactly the kind of bug that's invisible in testing -- and shows up as "my limit let me generate one more than it should have" -- in production. This function does the read-modify-write as a single -- atomic UPSERT instead.
create or replace function public.increment_usage_counter( p_user_id uuid, p_period_start date, p_period_end date ) returns public.usage_counters language plpgsql security definer set search_path = public as $$ declare v_row public.usage_counters; begin insert into public.usage_counters (user_id, period_start, period_end, generations_count) values (p_user_id, p_period_start, p_period_end, 1) on conflict (user_id, period_start) do update set generations_count = public.usage_counters.generations_count + 1 returning * into v_row;
return v_row; end; $$;
-- SECURITY DEFINER functions are exposed via PostgREST (and therefore -- callable by `anon`/`authenticated` through supabase-js .rpc()) by -- default, same as any other schema object — that would let a signed-in -- user call this directly and increment (or fabricate) their own usage -- row from the client, defeating the entire point of usage_counters -- having no client write policy (migration 0007). Explicitly revoking -- from anon/authenticated and granting only to service_role closes that -- gap; only the admin client (lib/supabase/admin.ts) can call this. revoke all on function public.increment_usage_counter(uuid, date, date) from public, anon, authenticated; grant execute on function public.increment_usage_counter(uuid, date, date) to service_role;

-- Stage 7 (Tools Gallery) needs `tools.description`, `tools.icon`, and -- `tools.category` for cards, categories, and search — none of which -- existed in migration 0006. This wasn't an oversight to quietly patch: -- Stage 6 (ToolRunner) genuinely never needed them, so they weren't added -- until a real consumer (this stage) required them. Additive-only, same -- discipline as migration 0011 — no existing column touched, nothing -- Stage 1-6 depends on changes shape. -- -- All three nullable: existing seed rows (migration 0010) predate these -- columns, and a tool without a category/description/icon should degrade -- gracefully in the gallery (see components/tools/gallery/ToolCard.tsx), -- not be forced to backfill placeholder content it doesn't have yet.
alter table public.tools add column description text, add column icon text, add column category text;
-- Supports category filtering — in-memory today (Stage 7 scope: dataset -- is a handful of tools), but this is exactly the kind of index that -- costs nothing now and avoids a migration later if/when category -- filtering moves server-side, per the project architecture doc's -- general "cheap now, expensive later" indexing rationale (see the -- Stage 3 audit for company_profiles/generations precedent). create index tools_category_idx on public.tools(category);

-- Backfills description/icon/category (migration 0012) onto the three -- tools seeded in migration 0010. Idempotent UPDATE, not a rewrite of the -- original seed INSERT — 0010 already ran; this only sets the new columns -- on the rows it created. Values are functional placeholders (accurate, -- minimal) — real per-tool copy is Stage 8-10 scope same as it always -- was; this migration exists only so the Gallery has something real to -- render against these three (still `is_active = false`, unchanged) rows -- rather than every field being empty.
update public.tools set description = 'Generate ready-to-run ad copy for your campaigns.', icon = '📣', category = 'Ads' where slug = 'ad-generator';
update public.tools set description = 'Draft marketing emails tailored to your audience.', icon = '✉️', category = 'Email' where slug = 'email-generator';
update public.tools set description = 'Create on-brand posts for your social channels.', icon = '📱', category = 'Social' where slug = 'social-generator';

-- Stage 8: the first real tool. Activates `ad-generator` (seeded inactive -- in migration 0010, category/description/icon added in 0013) with a -- real `config_schema` (format defined in Stage 6, -- lib/tool-config/schema.ts) and a real default template — the first -- content this project ships, not scaffold. -- -- Pure data (UPDATE + INSERT), no ALTER TABLE: Stage 3/6/7's schema -- already had everywhere this needed to write to -- (tools.config_schema jsonb, templates.prompt_template/required_fields) -- — worth noting as evidence that schema, not a gap this stage had to -- patch. -- -- Four fields, chosen for what an ad actually needs to be generated -- (platform, what's being advertised, an optional offer, a call to -- action) — not a UI/UX layout decision, a data requirement: the prompt -- template below literally can't produce a usable ad without knowing -- these. No fifth field ("tone") was added: the company profile already -- carries tone_of_voice into every prompt (lib/generation/prompt.ts, -- Stage 5) — a second, per-generation tone control would be redundant -- with data the pipeline already uses, not a missing feature.
update public.tools set is_active = true, config_schema = $json$ { "fields": [ { "type": "select", "name": "platform", "label": "Platform", "required": true, "options": [ { "label": "Facebook", "value": "Facebook" }, { "label": "Instagram", "value": "Instagram" }, { "label": "Google Search", "value": "Google Search" }, { "label": "LinkedIn", "value": "LinkedIn" }, { "label": "X (Twitter)", "value": "X (Twitter)" } ] }, { "type": "text", "name": "productOrService", "label": "Product or service being advertised", "required": true, "maxLength": 200 }, { "type": "textarea", "name": "offerDetails", "label": "Offer or promotion details", "helpText": "Optional — e.g. a discount, launch, or limited-time deal.", "required": false, "maxLength": 500, "rows": 3 }, { "type": "select", "name": "callToAction", "label": "Call to action", "required": true, "options": [ { "label": "Shop Now", "value": "Shop Now" }, { "label": "Learn More", "value": "Learn More" }, { "label": "Sign Up", "value": "Sign Up" }, { "label": "Get Started", "value": "Get Started" }, { "label": "Contact Us", "value": "Contact Us" } ] } ] } $json$::jsonb where slug = 'ad-generator';
-- One default template. `category` here is 'General' rather than a -- platform name (e.g. 'Facebook Ads') because `platform` is a field -- *within* this template, not a separate template per platform — it -- adapts to whichever platform the user picks, so it doesn't belong to -- one of the 16 platform-specific categories config/templates.json lists -- for the future Templates Library (Stage 10). Platform-specific -- templates, if wanted, are additional rows Stage 10 can add without -- touching this one. insert into public.templates (tool_id, slug, name, category, prompt_template, required_fields, is_premium) select id, 'ad-generator-default', 'Standard Ad', 'General', $prompt$Write a single, ready-to-publish ad for {{platform}}.
Product or service: {{productOrService}} Offer or promotion: {{offerDetails}} Call to action: {{callToAction}}
Follow {{platform}}'s typical ad copy length and conventions. Output only the ad copy itself — no explanations, no headers, no surrounding quotation marks.$prompt$, '["platform", "productOrService", "callToAction"]'::jsonb, false from public.tools where slug = 'ad-generator' on conflict (slug) do update set tool_id = excluded.tool_id, name = excluded.name, category = excluded.category, prompt_template = excluded.prompt_template, required_fields = excluded.required_fields, is_premium = excluded.is_premium;

-- Stage 9: second and third tools, via the exact same mechanism as -- migration 0014 (Stage 8) — pure data (UPDATE tools + INSERT templates), -- zero ALTER TABLE, zero application code changes. That absence of code -- changes is not an oversight; it is Stage 9's actual deliverable, per -- the brief: proof that lib/generation/catalog.ts, ToolRunner, -- ToolGallery, and lib/tools/query.ts are genuinely tool-agnostic, not -- ad-generator-shaped code that happens to work once. Nothing in this -- file requires any of those to change. -- -- Both tools follow the same 4-field shape Stage 8 established -- (type/topic-of-content, an optional offer, a required call to action) -- — that shape is repeated here because it's what any short promotional -- copy generator objectively needs, not because it was copied for -- consistency's sake. `offerDetails` and `callToAction` reuse the exact -- field names from ad-generator's schema where the concept is genuinely -- identical (an optional offer, a call-to-action choice); `emailType`/ -- `platform` and `productOrTopic`/`contentTopic` are named for what each -- tool actually asks, not forced to match ad-generator's -- `productOrService` — there is no shared code reading these keys across -- tools, so there is nothing to keep artificially uniform, and -- ad-generator's own (already-shipped, Stage 8) data is not touched here.
update public.tools set is_active = true, config_schema = $json$ { "fields": [ { "type": "select", "name": "emailType", "label": "Email type", "required": true, "options": [ { "label": "Promotional", "value": "Promotional" }, { "label": "Newsletter", "value": "Newsletter" }, { "label": "Announcement", "value": "Announcement" }, { "label": "Welcome email", "value": "Welcome email" }, { "label": "Re-engagement", "value": "Re-engagement" } ] }, { "type": "text", "name": "productOrTopic", "label": "What is this email about?", "required": true, "maxLength": 200 }, { "type": "textarea", "name": "offerDetails", "label": "Offer or key message", "helpText": "Optional — e.g. a discount, launch, or update worth highlighting.", "required": false, "maxLength": 500, "rows": 3 }, { "type": "select", "name": "callToAction", "label": "Call to action", "required": true, "options": [ { "label": "Shop Now", "value": "Shop Now" }, { "label": "Learn More", "value": "Learn More" }, { "label": "Sign Up", "value": "Sign Up" }, { "label": "Book a Call", "value": "Book a Call" }, { "label": "Reply to This Email", "value": "Reply to This Email" } ] } ] } $json$::jsonb where slug = 'email-generator';
update public.tools set is_active = true, config_schema = $json$ { "fields": [ { "type": "select", "name": "platform", "label": "Platform", "required": true, "options": [ { "label": "Instagram", "value": "Instagram" }, { "label": "Facebook", "value": "Facebook" }, { "label": "LinkedIn", "value": "LinkedIn" }, { "label": "X (Twitter)", "value": "X (Twitter)" }, { "label": "TikTok", "value": "TikTok" } ] }, { "type": "text", "name": "contentTopic", "label": "What is this post about?", "required": true, "maxLength": 200 }, { "type": "textarea", "name": "offerDetails", "label": "Offer or key message", "helpText": "Optional — e.g. a discount, launch, or update worth highlighting.", "required": false, "maxLength": 500, "rows": 3 }, { "type": "select", "name": "callToAction", "label": "Call to action", "required": true, "options": [ { "label": "Shop Now", "value": "Shop Now" }, { "label": "Learn More", "value": "Learn More" }, { "label": "Follow Us", "value": "Follow Us" }, { "label": "Sign Up", "value": "Sign Up" }, { "label": "Comment Below", "value": "Comment Below" } ] } ] } $json$::jsonb where slug = 'social-generator';
-- Both templates: category 'General', same reasoning as ad-generator's -- (migration 0014) — each adapts to whichever email type / platform the -- user picks via its own field, so neither belongs to one of the 16 -- platform-specific categories config/templates.json lists for the -- future Templates Library (Stage 10).
insert into public.templates (tool_id, slug, name, category, prompt_template, required_fields, is_premium) select id, 'email-generator-default', 'Standard Email', 'General', $prompt$Write a single, ready-to-send marketing email.
Email type: {{emailType}} Topic: {{productOrTopic}} Offer or key message: {{offerDetails}} Call to action: {{callToAction}}
Start with a subject line on its own line prefixed "Subject: ", then a blank line, then the email body. Output only that — no explanations, no extra commentary, no surrounding quotation marks.$prompt$, '["emailType", "productOrTopic", "callToAction"]'::jsonb, false from public.tools where slug = 'email-generator' on conflict (slug) do update set tool_id = excluded.tool_id, name = excluded.name, category = excluded.category, prompt_template = excluded.prompt_template, required_fields = excluded.required_fields, is_premium = excluded.is_premium;
insert into public.templates (tool_id, slug, name, category, prompt_template, required_fields, is_premium) select id, 'social-generator-default', 'Standard Social Post', 'General', $prompt$Write a single, ready-to-publish social media post for {{platform}}.
Topic: {{contentTopic}} Offer or key message: {{offerDetails}} Call to action: {{callToAction}}
Follow {{platform}}'s typical length, tone and hashtag conventions. Output only the post itself — no explanations, no headers, no surrounding quotation marks.$prompt$, '["platform", "contentTopic", "callToAction"]'::jsonb, false from public.tools where slug = 'social-generator' on conflict (slug) do update set tool_id = excluded.tool_id, name = excluded.name, category = excluded.category, prompt_template = excluded.prompt_template, required_fields = excluded.required_fields, is_premium = excluded.is_premium;
